/// Checked H-CLAIMS generation bounds.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ClaimLimits {
    /// Maximum effective-universe modules.
    pub max_modules: u64,
    /// Maximum distinct variable claim ids.
    pub max_claims: u64,
    /// Maximum variable holder observations, in addition to the fixed global
    /// four-role fill setup.
    pub max_observations: u64,
    /// Maximum global layer indices.
    pub max_layers: u64,
    /// Maximum bytes per variable text component.
    ///
    /// Object ids are UUID syntax, which needs 36 bytes, so the accepted floor is
    /// 36 rather than the packet's 8-byte variable-text floor: a smaller ceiling
    /// cannot be honoured without silently widening it after acceptance.
    pub max_text_bytes: u64,
}

/// Validate the packet's safety ceilings before any strategy allocates.
///
/// Modules `3..=7`, claims `1..=8`, observations `2..=16`, layers `2..=4` and
/// variable text `36..=64` bytes (UUID-syntax object ids need 36 bytes; the
/// packet's 8-byte floor applies to raw text components). Conversion and product
/// checks are explicit so an out-of-ceiling profile is rejected with the
/// offending bound named instead of being narrowed silently.
pub fn checked_claim_limits(
    max_modules: u64,
    max_claims: u64,
    max_observations: u64,
    max_layers: u64,
    max_text_bytes: u64,
) -> Result<ClaimLimits, String> {
    check_bound("max_modules", max_modules, 3, 7)?;
    check_bound("max_claims", max_claims, 1, 8)?;
    check_bound("max_observations", max_observations, 2, 16)?;
    check_bound("max_layers", max_layers, 2, 4)?;
    check_text_bound(max_text_bytes)?;

    let modules =
        usize::try_from(max_modules).map_err(|_| String::from("max_modules does not fit usize"))?;
    let claims =
        usize::try_from(max_claims).map_err(|_| String::from("max_claims does not fit usize"))?;
    let observations = usize::try_from(max_observations)
        .map_err(|_| String::from("max_observations does not fit usize"))?;
    let _layers =
        u32::try_from(max_layers).map_err(|_| String::from("max_layers does not fit u32"))?;
    let text_bytes = usize::try_from(max_text_bytes)
        .map_err(|_| String::from("max_text_bytes does not fit usize"))?;

    modules
        .checked_mul(observations)
        .ok_or_else(|| String::from("max_modules * max_observations overflows usize"))?;
    claims
        .checked_mul(observations)
        .ok_or_else(|| String::from("max_claims * max_observations overflows usize"))?;
    observations
        .checked_add(FILL_CLAIM_IDS.len())
        .ok_or_else(|| String::from("max_observations + fixed fill setup overflows usize"))?;
    text_bytes
        .checked_add(module_id_overhead())
        .ok_or_else(|| String::from("max_text_bytes + module id overhead overflows usize"))?;

    Ok(ClaimLimits {
        max_modules,
        max_claims,
        max_observations,
        max_layers,
        max_text_bytes,
    })
}

fn check_bound(name: &str, value: u64, low: u64, high: u64) -> Result<(), String> {
    if (low..=high).contains(&value) {
        Ok(())
    } else {
        Err(format!("{name} must be in {low}..={high}, got {value}"))
    }
}

/// The variable-text ceiling must admit the UUID-syntax object ids the generator
/// produces. Rejecting a smaller value up front is the only way to keep the
/// accepted bound honest: `uuid_text` must never widen it after the fact.
fn check_text_bound(value: u64) -> Result<(), String> {
    if (36..=64).contains(&value) {
        Ok(())
    } else {
        Err(format!(
            "max_text_bytes must be in 36..=64, got {value} (object ids are UUID \
             syntax, which needs 36 bytes)"
        ))
    }
}

fn module_id_overhead() -> usize {
    // `com.pbt.claim-NN-` is shorter than this fixed headroom.
    32
}

/// One tagged generation mode. One mode per case so shrinking cannot erase the
/// fault: every variant either names its claim or names a fixed witness shape.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum ClaimMode {
    /// Global multiplicity of one configured fill id is allowed.
    FillGlobalMultiplicity(&'static str),
    /// Global absence of one configured fill id yields the exact
    /// `MissingDependency`.
    FillGlobalAbsent(&'static str),
    /// Global fill multiplicity does not exempt a per-region duplicate.
    FillRegionDuplicate(&'static str),
    /// One finite family-support global is exempt.
    FamilyGlobalExempt(&'static str),
    /// An arbitrary `support-family:<suffix>` is not exempt.
    FamilySuffixNotExempt,
    /// Global ordinary holders conflict pairwise; duplicate observations do not.
    OrdinaryGlobal,
    /// `claim:raft-fill` is ordinary, not a configured fill exception.
    RaftGlobal,
    /// Per-region typed scope collisions.
    RegionScopes,
    /// Delimiter-rich ids must stay distinct typed tuples.
    DelimiterScopes,
    /// Exact shared-field write ordering and support-root aggregation.
    WriteConflicts,
    /// Effective-universe module and capability membership.
    MissingUniverse,
    /// Direct and transitive cross-stage legality.
    CrossStage,
    /// Transitive-only witness: A and B share one stage, B requires C in a later
    /// stage, and A requires only B. A direct-only rule finds nothing for A.
    CrossStageSharedStage,
    /// Enabled-only effective universe after removing locally tagged modules.
    DisabledUniverse,
    /// Same-region cross-layer stable-claim witness.
    StableSameRegion(&'static str),
    /// Different-region different-layer stable-claim witness.
    StableCrossRegion(&'static str),
    /// Three distinct stable holders in three regions and different layers: the
    /// reported scope must be each pair's own first holder's region.
    StableThreeHolders(&'static str),
    /// One module may stay stable across layers.
    StableSameModuleAcrossLayers,
    /// Different objects stay independent.
    StableDistinctObjects,
    /// Declared transition-capable claims may change holder across layers.
    TransitionCapable(&'static str),
    /// Declarative startup selection/pairing domain driven through the real
    /// dedup, held-claim resolver and family-pairing seams.
    SelectionPairing(SelectionWitness),
}

/// The typed `wall_generator` / `spiral_vase` selector witness.
///
/// It is encoded in the tagged mode, and the mode is drawn from a `no_shrink`
/// source, so Proptest can simplify the declarative domain but can never switch
/// the selector branch underneath the assertion.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum SelectionWitness {
    /// Absent selector (`None`).
    Absent,
    /// `ConfigValue::String("classic")`.
    Classic,
    /// `ConfigValue::String("arachne")`.
    Arachne,
    /// An unrecognized string value falls back to classic.
    Unrecognized,
    /// Classic with `spiral_vase = true`.
    ClassicSpiralVase,
    /// Arachne with `spiral_vase = true`; spiral-vase forces classic.
    ArachneSpiralVase,
}

impl SelectionWitness {
    /// Every selector witness the pre-sample must reach.
    pub const ALL: [SelectionWitness; 6] = [
        SelectionWitness::Absent,
        SelectionWitness::Classic,
        SelectionWitness::Arachne,
        SelectionWitness::Unrecognized,
        SelectionWitness::ClassicSpiralVase,
        SelectionWitness::ArachneSpiralVase,
    ];

    /// The exact typed selector handed to the real dedup seam.
    fn wall_generator(self) -> Option<ConfigValue> {
        match self {
            SelectionWitness::Absent => None,
            SelectionWitness::Classic | SelectionWitness::ClassicSpiralVase => {
                Some(ConfigValue::String(String::from("classic")))
            }
            SelectionWitness::Arachne | SelectionWitness::ArachneSpiralVase => {
                Some(ConfigValue::String(String::from("arachne")))
            }
            SelectionWitness::Unrecognized => Some(ConfigValue::String(String::from("banana"))),
        }
    }

    fn spiral_vase(self) -> bool {
        matches!(
            self,
            SelectionWitness::ClassicSpiralVase | SelectionWitness::ArachneSpiralVase
        )
    }

    /// The perimeter module the selector must prefer, independently derived from
    /// the typed selector rules (spiral-vase forces classic).
    fn preferred_perimeter(self) -> &'static str {
        if self.spiral_vase() || !matches!(self, SelectionWitness::Arachne) {
            "com.core.classic-perimeters"
        } else {
            "com.core.arachne-perimeters"
        }
    }
}

impl ClaimMode {
    /// Every variant the pre-sample must reach when the bounds admit it.
    ///
    /// `ClaimMode::available` filters the variants whose fixed witness cannot fit
    /// a narrow profile; at the packet's full ceilings every variant runs.
    pub const ALL: [ClaimMode; 48] = [
        ClaimMode::FillGlobalMultiplicity(EXPECTED_FILL_CLAIM_IDS[0]),
        ClaimMode::FillGlobalMultiplicity(EXPECTED_FILL_CLAIM_IDS[1]),
        ClaimMode::FillGlobalMultiplicity(EXPECTED_FILL_CLAIM_IDS[2]),
        ClaimMode::FillGlobalMultiplicity(EXPECTED_FILL_CLAIM_IDS[3]),
        ClaimMode::FillGlobalAbsent(EXPECTED_FILL_CLAIM_IDS[0]),
        ClaimMode::FillGlobalAbsent(EXPECTED_FILL_CLAIM_IDS[1]),
        ClaimMode::FillGlobalAbsent(EXPECTED_FILL_CLAIM_IDS[2]),
        ClaimMode::FillGlobalAbsent(EXPECTED_FILL_CLAIM_IDS[3]),
        ClaimMode::FillRegionDuplicate(EXPECTED_FILL_CLAIM_IDS[0]),
        ClaimMode::FillRegionDuplicate(EXPECTED_FILL_CLAIM_IDS[1]),
        ClaimMode::FillRegionDuplicate(EXPECTED_FILL_CLAIM_IDS[2]),
        ClaimMode::FillRegionDuplicate(EXPECTED_FILL_CLAIM_IDS[3]),
        ClaimMode::FamilyGlobalExempt(FAMILY_SUPPORT_GLOBAL_CLAIMS[0]),
        ClaimMode::FamilyGlobalExempt(FAMILY_SUPPORT_GLOBAL_CLAIMS[1]),
        ClaimMode::FamilyGlobalExempt(FAMILY_SUPPORT_GLOBAL_CLAIMS[2]),
        ClaimMode::FamilyGlobalExempt(FAMILY_SUPPORT_GLOBAL_CLAIMS[3]),
        ClaimMode::FamilySuffixNotExempt,
        ClaimMode::OrdinaryGlobal,
        ClaimMode::RaftGlobal,
        ClaimMode::RegionScopes,
        ClaimMode::DelimiterScopes,
        ClaimMode::WriteConflicts,
        ClaimMode::MissingUniverse,
        ClaimMode::CrossStage,
        ClaimMode::CrossStageSharedStage,
        ClaimMode::DisabledUniverse,
        ClaimMode::StableSameRegion(STABLE_CLAIM_IDS[0]),
        ClaimMode::StableSameRegion(STABLE_CLAIM_IDS[1]),
        ClaimMode::StableSameRegion(STABLE_CLAIM_IDS[2]),
        ClaimMode::StableSameRegion(STABLE_CLAIM_IDS[3]),
        ClaimMode::StableCrossRegion(STABLE_CLAIM_IDS[0]),
        ClaimMode::StableCrossRegion(STABLE_CLAIM_IDS[1]),
        ClaimMode::StableCrossRegion(STABLE_CLAIM_IDS[2]),
        ClaimMode::StableCrossRegion(STABLE_CLAIM_IDS[3]),
        ClaimMode::StableThreeHolders(STABLE_CLAIM_IDS[0]),
        ClaimMode::StableThreeHolders(STABLE_CLAIM_IDS[1]),
        ClaimMode::StableThreeHolders(STABLE_CLAIM_IDS[2]),
        ClaimMode::StableThreeHolders(STABLE_CLAIM_IDS[3]),
        ClaimMode::StableSameModuleAcrossLayers,
        ClaimMode::StableDistinctObjects,
        ClaimMode::TransitionCapable(TRANSITION_CAPABLE_CLAIM_IDS[0]),
        ClaimMode::TransitionCapable(TRANSITION_CAPABLE_CLAIM_IDS[1]),
        ClaimMode::SelectionPairing(SelectionWitness::Absent),
        ClaimMode::SelectionPairing(SelectionWitness::Classic),
        ClaimMode::SelectionPairing(SelectionWitness::Arachne),
        ClaimMode::SelectionPairing(SelectionWitness::Unrecognized),
        ClaimMode::SelectionPairing(SelectionWitness::ClassicSpiralVase),
        ClaimMode::SelectionPairing(SelectionWitness::ArachneSpiralVase),
    ];

    /// Whether the accepted bounds can carry this mode's fixed witness.
    ///
    /// Only the three-holder mode is conditional: it adds three variable holder
    /// observations on top of the fixed four-role fill setup, so an
    /// `max_observations` of 2 cannot express it without exceeding the accepted
    /// bound. Every other mode fits every accepted profile.
    #[must_use]
    pub fn is_available(&self, limits: &ClaimLimits) -> bool {
        match self {
            ClaimMode::StableThreeHolders(_) => limits.max_observations >= 3,
            _ => true,
        }
    }
}

/// The modes the accepted bounds can carry, in `ClaimMode::ALL` order.
#[must_use]
pub fn available_modes(limits: &ClaimLimits) -> Vec<ClaimMode> {
    ClaimMode::ALL
        .iter()
        .copied()
        .filter(|mode| mode.is_available(limits))
        .collect()
}

/// One generated effective universe plus the validation carriers.
#[derive(Debug, Clone)]
pub struct ClaimCase {
    /// Tagged generation mode.
    pub mode: ClaimMode,
    /// Declared effective-universe modules.
    pub modules: Vec<LoadedModule>,
    /// Stage-local DAGs built from those modules.
    pub stage_dags: Vec<StageDag>,
    /// Holder observations, including the fixed global fill setup.
    pub claim_holders: Vec<ClaimHolder>,
    /// Modules tagged "disabled"; removed before the production request.
    pub disabled: Vec<ModuleId>,
    /// Every generated variable text component (object ids and raw id parts).
    ///
    /// The generated-size assertion checks these against `max_text_bytes`; fixed
    /// normative names and constant region ids are deliberately absent.
    pub variable_text: Vec<String>,
}

impl ClaimCase {
    /// Enabled modules after removing the disabled tag.
    #[must_use]
    pub fn enabled_modules(&self) -> Vec<LoadedModule> {
        self.modules
            .iter()
            .filter(|module| !self.is_disabled(module.id()))
            .cloned()
            .collect()
    }

    /// Holder observations after removing the disabled tag.
    #[must_use]
    pub fn enabled_holders(&self) -> Vec<ClaimHolder> {
        self.claim_holders
            .iter()
            .filter(|holder| !self.is_disabled(&holder.module_id))
            .cloned()
            .collect()
    }

    /// Stage DAGs after removing the disabled modules' nodes.
    #[must_use]
    pub fn enabled_stage_dags(&self) -> Vec<StageDag> {
        self.stage_dags
            .iter()
            .map(|dag| StageDag {
                stage: dag.stage.clone(),
                nodes: dag
                    .nodes
                    .iter()
                    .filter(|node| !self.is_disabled(&node.module_id))
                    .cloned()
                    .collect(),
            })
            .collect()
    }

    /// Production request built from the enabled-only universe.
    #[must_use]
    pub fn build_request(&self) -> DagValidationRequest {
        request_from(
            self.enabled_modules(),
            self.enabled_stage_dags(),
            self.enabled_holders(),
        )
    }

    /// Production request retaining the disabled module, used only to prove the
    /// removal changed the verdict by exactly the disabled contributions.
    #[must_use]
    pub fn unfiltered_request(&self) -> DagValidationRequest {
        request_from(
            self.modules.clone(),
            self.stage_dags.clone(),
            self.claim_holders.clone(),
        )
    }

    fn is_disabled(&self, module_id: &str) -> bool {
        self.disabled
            .iter()
            .any(|disabled| disabled.as_str() == module_id)
    }

    /// Every distinct claim id the case mentions, excluding the four documented
    /// fixed fill-role ids.
    ///
    /// The fixed four-role setup is additional budget in the packet's own bound
    /// description (like observations), so it is excluded here; every other id
    /// — including claims a module only *requires* — counts against
    /// `max_claims`.
    #[must_use]
    pub fn variable_claim_ids(&self) -> BTreeSet<&str> {
        let mut claims = BTreeSet::new();
        for module in &self.modules {
            claims.extend(module.claims().iter().map(String::as_str));
            claims.extend(module.requires_claims().iter().map(String::as_str));
        }
        for holder in &self.claim_holders {
            claims.insert(holder.claim.as_str());
        }
        claims.retain(|claim| !FILL_CLAIM_IDS.contains(claim));
        claims
    }
}

