/// Build one loaded module with fixed compatible versions and a placeholder
/// wasm path. Nothing reads the path; the record is a scheduler input only.
pub fn module_with(
    id: &str,
    stage: &str,
    claims: Vec<String>,
    reads: Vec<String>,
    writes: Vec<String>,
    requires_modules: Vec<String>,
    requires_claims: Vec<String>,
) -> LoadedModule {
    LoadedModuleBuilder::new(
        id,
        semver(0, 1, 0),
        stage,
        "pbt",
        PathBuf::from("fixtures/pbt-placeholder.wasm"),
    )
    .claims(claims)
    .ir_reads(reads)
    .ir_writes(writes)
    .requires_modules(requires_modules)
    .requires_claims(requires_claims)
    .min_host_version(semver(0, 1, 0))
    .min_ir_schema(semver(1, 0, 0))
    .max_ir_schema(semver(2, 0, 0))
    .layer_parallel_safe(true)
    .placeholder_wasm(true)
    .build()
}

/// Build one module with no claims, accesses or dependencies.
pub fn plain_module(id: &str, stage: &str) -> LoadedModule {
    module_with(
        id,
        stage,
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Vec::new(),
    )
}

/// Global holder observation.
pub fn global_holder(claim: &str, module: &str) -> ClaimHolder {
    ClaimHolder {
        claim: claim.to_string(),
        module_id: module.to_string(),
        scope: ConflictScope::Global,
    }
}

/// Per-region holder observation; `layer` is the typed global layer index.
pub fn region_holder(
    claim: &str,
    module: &str,
    object_id: &str,
    region_id: &str,
    layer: Option<u32>,
) -> ClaimHolder {
    ClaimHolder {
        claim: claim.to_string(),
        module_id: module.to_string(),
        scope: ConflictScope::Region {
            object_id: object_id.to_string(),
            region_id: region_id.to_string(),
            global_layer_index: layer,
        },
    }
}

/// The fixed global fill setup: one module holding every configured fill id.
pub fn fixed_fill_holders(module: &str) -> Vec<ClaimHolder> {
    FILL_CLAIM_IDS
        .iter()
        .map(|claim| global_holder(claim, module))
        .collect()
}

/// Build the stage DAG for one canonical stage from the supplied modules.
pub fn single_stage_dag(modules: &[LoadedModule], stage: &str) -> StageDag {
    let producers: Vec<&dyn Producer> = modules
        .iter()
        .map(|module| module as &dyn Producer)
        .collect();
    let nodes =
        build_intra_stage_dag(stage.to_string(), &producers).expect("intra-stage DAG build");
    let expected = modules
        .iter()
        .filter(|module| module.stage() == stage)
        .count();
    assert_eq!(
        nodes.len(),
        expected,
        "the stage DAG must contain exactly the modules declared in stage {stage}"
    );
    StageDag {
        stage: stage.to_string(),
        nodes,
    }
}

/// Build one stage DAG per canonical stage present in `modules`.
pub fn stage_dags_for(modules: &[LoadedModule]) -> Vec<StageDag> {
    let mut stages: Vec<&str> = modules.iter().map(LoadedModule::stage).collect();
    stages.sort_unstable();
    stages.dedup();
    stages
        .into_iter()
        .map(|stage| single_stage_dag(modules, stage))
        .collect()
}

/// Build a request from explicit carriers.
pub fn request_from(
    modules: Vec<LoadedModule>,
    stage_dags: Vec<StageDag>,
    claim_holders: Vec<ClaimHolder>,
) -> DagValidationRequest {
    // exhaustive: every validation carrier must be populated from the case; there is no safe default for modules, stage DAGs or holder observations.
    DagValidationRequest {
        modules,
        stage_dags,
        host_ir_schema_version: semver(1, 0, 0),
        host_version: semver(0, 1, 0),
        claim_holders,
        access_audits: Vec::new(),
    }
}

/// Independent stage rank derived from the canonical `STAGE_ORDER`.
pub fn stage_ranks() -> BTreeMap<&'static str, usize> {
    STAGE_ORDER
        .iter()
        .enumerate()
        .map(|(index, stage)| (*stage, index))
        .collect()
}

