/// Typed claim scope used by the model. It is an ordered value, never a
/// concatenated string.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub enum ScopeModel {
    /// Whole print.
    Global,
    /// Object-wide stability key for the four stable claims.
    Object {
        /// Original object identity.
        object_id: String,
    },
    /// One typed region observation.
    Region {
        /// Original object identity.
        object_id: String,
        /// Original region identity.
        region_id: String,
        /// Optional global layer index.
        layer: Option<u32>,
    },
}

/// Covered validation pass tag (ordered for normalized-set comparison).
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum PassTag {
    /// `DagValidationPass::GlobalClaimConflicts`.
    GlobalClaims,
    /// `DagValidationPass::PerRegionClaimConflicts`.
    PerRegionClaims,
    /// `DagValidationPass::MissingDependencies`.
    Missing,
    /// `DagValidationPass::WriteConflicts`.
    Write,
    /// `DagValidationPass::CrossStageDependencyLegality`.
    CrossStage,
}

/// One normalized expected/observed diagnostic.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub enum DiagKey {
    /// `SchedulerError::ClaimConflict`.
    Claim {
        /// Emitting pass.
        pass: PassTag,
        /// Claim id.
        claim: String,
        /// Lexically first holder.
        module_a: ModuleId,
        /// Lexically second holder.
        module_b: ModuleId,
        /// Typed scope.
        scope: ScopeModel,
    },
    /// `SchedulerError::MissingDependency`.
    Missing {
        /// Emitting pass (`GlobalClaims` for the fill-role coverage check,
        /// `Missing` for module/capability membership).
        pass: PassTag,
        /// Requesting module (or `fill-role-claim:<id>`).
        module: ModuleId,
        /// Missing module id or capability id.
        requires: ModuleId,
    },
    /// `SchedulerError::WriteConflict`, pair normalized to a lexical order.
    Write {
        /// Shared exact path.
        field: String,
        /// Lexically first writer.
        module_a: ModuleId,
        /// Lexically second writer.
        module_b: ModuleId,
        /// Stage containing both writers.
        stage: String,
        /// Whether the pass judged the pair orderable.
        orderable: bool,
    },
    /// `SchedulerError::CrossStageDependency`.
    CrossStage {
        /// Requesting module.
        module: ModuleId,
        /// Required module.
        requires: ModuleId,
        /// Requesting module's stage.
        module_stage: String,
        /// Required module's stage.
        required_stage: String,
    },
    /// A covered pass emitted a variant this model does not expect.
    Unexpected {
        /// Emitting pass.
        pass: PassTag,
        /// Debug rendering of the payload.
        detail: String,
    },
}

/// Expected normalized diagnostics for a case's enabled-only universe.
#[must_use]
pub fn expected_diagnostics(case: &ClaimCase) -> BTreeSet<DiagKey> {
    let modules = case.enabled_modules();
    let holders = case.enabled_holders();
    let stage_dags = case.enabled_stage_dags();
    let mut expected = BTreeSet::new();
    model_claims(&modules, &holders, &mut expected);
    model_writes(&stage_dags, &holders, &mut expected);
    model_cross_stage(&modules, &mut expected);
    expected
}

fn model_claims(
    modules: &[LoadedModule],
    holders: &[ClaimHolder],
    expected: &mut BTreeSet<DiagKey>,
) {
    // Pass 2: global holders, grouped by claim only.
    let mut global: BTreeMap<String, Vec<(ModuleId, ConflictScope)>> = BTreeMap::new();
    for holder in holders {
        if matches!(holder.scope, ConflictScope::Global) {
            global
                .entry(holder.claim.clone())
                .or_default()
                .push((holder.module_id.clone(), holder.scope.clone()));
        }
    }

    for fill_claim in FILL_CLAIM_IDS {
        if !global.contains_key(*fill_claim) {
            expected.insert(DiagKey::Missing {
                pass: PassTag::GlobalClaims,
                module: format!("fill-role-claim:{fill_claim}"),
                requires: format!("no module holds {fill_claim}"),
            });
        }
    }

    for (claim, observations) in &global {
        let effective = effective_modules(observations);
        if effective.len() < 2 {
            continue;
        }
        if FILL_CLAIM_IDS.contains(&claim.as_str())
            || FAMILY_SUPPORT_GLOBAL_CLAIMS.contains(&claim.as_str())
        {
            continue;
        }
        push_pairwise(expected, PassTag::GlobalClaims, claim, &effective, |_| {
            ScopeModel::Global
        });
    }

    // Pass 3: per-region holders. The four stable claims are compared
    // object-wide (every region and layer of one object shares a key), so a
    // holder change across regions cannot masquerade as two separate scopes.
    let mut regions: BTreeMap<(String, ScopeModel), Vec<(ModuleId, ConflictScope)>> =
        BTreeMap::new();
    for holder in holders {
        let ConflictScope::Region {
            object_id,
            region_id,
            global_layer_index,
        } = &holder.scope
        else {
            continue;
        };
        let key = if STABLE_CLAIM_IDS.contains(&holder.claim.as_str()) {
            ScopeModel::Object {
                object_id: object_id.clone(),
            }
        } else {
            ScopeModel::Region {
                object_id: object_id.clone(),
                region_id: region_id.clone(),
                layer: *global_layer_index,
            }
        };
        regions
            .entry((holder.claim.clone(), key))
            .or_default()
            .push((holder.module_id.clone(), holder.scope.clone()));
    }

    for ((claim, key), observations) in &regions {
        let effective = effective_modules(observations);
        if effective.len() < 2 {
            continue;
        }
        match key {
            ScopeModel::Global => push_pairwise(
                expected,
                PassTag::PerRegionClaims,
                claim,
                &effective,
                |_| ScopeModel::Global,
            ),
            ScopeModel::Region { .. } => {
                let scope = key.clone();
                push_pairwise(
                    expected,
                    PassTag::PerRegionClaims,
                    claim,
                    &effective,
                    |_| scope.clone(),
                );
            }
            ScopeModel::Object { object_id } => {
                // The object-wide key has no single region of its own: production
                // reports the conflict inside the *first holder of each pair*'s
                // original region, pinned without a layer. Computing one region
                // for the whole group would mis-report every pair whose first
                // holder is not the lexically first holder overall.
                push_pairwise(
                    expected,
                    PassTag::PerRegionClaims,
                    claim,
                    &effective,
                    |observation| match &observation.1 {
                        ConflictScope::Region { region_id, .. } => ScopeModel::Region {
                            object_id: object_id.clone(),
                            region_id: region_id.clone(),
                            layer: None,
                        },
                        ConflictScope::Global => ScopeModel::Region {
                            object_id: object_id.clone(),
                            region_id: String::new(),
                            layer: None,
                        },
                    },
                );
            }
        }
    }

    // Pass 5: exact effective-universe membership for modules and capabilities.
    let universe: BTreeSet<&str> = modules.iter().map(LoadedModule::id).collect();
    let available_claims: BTreeSet<&str> =
        holders.iter().map(|holder| holder.claim.as_str()).collect();
    for module in modules {
        for required in module.requires_modules() {
            if !universe.contains(required.as_str()) {
                expected.insert(DiagKey::Missing {
                    pass: PassTag::Missing,
                    module: module.id().to_string(),
                    requires: required.clone(),
                });
            }
        }
        for required in module.requires_claims() {
            if !available_claims.contains(required.as_str()) {
                expected.insert(DiagKey::Missing {
                    pass: PassTag::Missing,
                    module: module.id().to_string(),
                    requires: required.clone(),
                });
            }
        }
    }
}

fn effective_modules(observations: &[(ModuleId, ConflictScope)]) -> Vec<(ModuleId, ConflictScope)> {
    let mut seen = BTreeSet::new();
    let mut effective = Vec::new();
    for (module_id, scope) in observations {
        if seen.insert(module_id.clone()) {
            effective.push((module_id.clone(), scope.clone()));
        }
    }
    effective.sort_by(|left, right| left.0.cmp(&right.0));
    effective
}

fn push_pairwise<F>(
    expected: &mut BTreeSet<DiagKey>,
    pass: PassTag,
    claim: &str,
    effective: &[(ModuleId, ConflictScope)],
    scope_for: F,
) where
    F: Fn(&(ModuleId, ConflictScope)) -> ScopeModel,
{
    for left in 0..effective.len() {
        for right in (left + 1)..effective.len() {
            expected.insert(DiagKey::Claim {
                pass,
                claim: claim.to_string(),
                module_a: effective[left].0.clone(),
                module_b: effective[right].0.clone(),
                scope: scope_for(&effective[left]),
            });
        }
    }
}

fn model_writes(
    stage_dags: &[StageDag],
    holders: &[ClaimHolder],
    expected: &mut BTreeSet<DiagKey>,
) {
    let family_holders: BTreeSet<ModuleId> = holders
        .iter()
        .filter(|holder| FAMILY_SUPPORT_GLOBAL_CLAIMS.contains(&holder.claim.as_str()))
        .map(|holder| holder.module_id.clone())
        .collect();

    for stage_dag in stage_dags {
        let reachability = reachability(&stage_dag.nodes);
        for left in 0..stage_dag.nodes.len() {
            for right in (left + 1)..stage_dag.nodes.len() {
                let left_node = &stage_dag.nodes[left];
                let right_node = &stage_dag.nodes[right];
                let mut shared: Vec<String> = left_node
                    .ir_writes
                    .iter()
                    .filter(|field| right_node.ir_writes.contains(field))
                    .cloned()
                    .collect();
                shared.sort();
                shared.dedup();

                for field in shared {
                    let left_transforms_right = right_node.ir_reads.contains(&field)
                        && reachable(&reachability, &left_node.module_id, &right_node.module_id);
                    let right_transforms_left = left_node.ir_reads.contains(&field)
                        && reachable(&reachability, &right_node.module_id, &left_node.module_id);
                    let family_orderable = family_holders.contains(&left_node.module_id)
                        && family_holders.contains(&right_node.module_id)
                        && is_support_root(&field);
                    if left_transforms_right || right_transforms_left || family_orderable {
                        continue;
                    }

                    let (module_a, module_b) =
                        lexical_pair(left_node.module_id.clone(), right_node.module_id.clone());
                    expected.insert(DiagKey::Write {
                        field,
                        module_a,
                        module_b,
                        stage: stage_dag.stage.clone(),
                        orderable: false,
                    });
                }
            }
        }
    }
}

fn is_support_root(field: &str) -> bool {
    field == "SupportPlanIR"
        || field.starts_with("SupportPlanIR.")
        || field == "SupportIR"
        || field.starts_with("SupportIR.")
}

fn reachability(nodes: &[slicer_scheduler::ModuleNode]) -> BTreeMap<ModuleId, BTreeSet<ModuleId>> {
    let adjacency: BTreeMap<ModuleId, Vec<ModuleId>> = nodes
        .iter()
        .map(|node| {
            (
                node.module_id.clone(),
                node.edges_to.iter().map(|edge| edge.to.clone()).collect(),
            )
        })
        .collect();
    let mut reachable_from = BTreeMap::new();
    for node in nodes {
        let mut visited = BTreeSet::new();
        let mut queue: Vec<ModuleId> = adjacency.get(&node.module_id).cloned().unwrap_or_default();
        while let Some(current) = queue.pop() {
            if !visited.insert(current.clone()) {
                continue;
            }
            if let Some(next) = adjacency.get(&current) {
                queue.extend(next.iter().cloned());
            }
        }
        reachable_from.insert(node.module_id.clone(), visited);
    }
    reachable_from
}

fn reachable(reachability: &BTreeMap<ModuleId, BTreeSet<ModuleId>>, from: &str, to: &str) -> bool {
    reachability
        .get(from)
        .is_some_and(|targets| targets.contains(to))
}

fn lexical_pair(left: ModuleId, right: ModuleId) -> (ModuleId, ModuleId) {
    if left <= right {
        (left, right)
    } else {
        (right, left)
    }
}

fn model_cross_stage(modules: &[LoadedModule], expected: &mut BTreeSet<DiagKey>) {
    let ranks = stage_ranks();
    let by_id: BTreeMap<&str, &LoadedModule> =
        modules.iter().map(|module| (module.id(), module)).collect();

    for module in modules {
        let Some(module_rank) = ranks.get(module.stage()) else {
            continue;
        };
        for required in module.requires_modules() {
            let Some(required_module) = by_id.get(required.as_str()) else {
                continue;
            };
            let Some(required_rank) = ranks.get(required_module.stage()) else {
                continue;
            };
            if required_rank > module_rank {
                expected.insert(DiagKey::CrossStage {
                    module: module.id().to_string(),
                    requires: required_module.id().to_string(),
                    module_stage: module.stage().to_string(),
                    required_stage: required_module.stage().to_string(),
                });
            }
        }
    }
}

/// Modules with at least one real `requires_modules` path ending at a later
/// stage. Production emits at most one `TransitiveStageDependency` per module
/// and the route is unspecified, so the property asserts existence and path
/// validity instead of a particular BFS route.
#[must_use]
pub fn expected_transitive_modules(modules: &[LoadedModule]) -> BTreeSet<ModuleId> {
    let ranks = stage_ranks();
    let by_id: BTreeMap<&str, &LoadedModule> =
        modules.iter().map(|module| (module.id(), module)).collect();
    let adjacency: BTreeMap<&str, Vec<&str>> = modules
        .iter()
        .map(|module| {
            (
                module.id(),
                module
                    .requires_modules()
                    .iter()
                    .map(String::as_str)
                    .filter(|required| by_id.contains_key(*required))
                    .collect(),
            )
        })
        .collect();

    let mut expected = BTreeSet::new();
    for module in modules {
        let Some(module_rank) = ranks.get(module.stage()) else {
            continue;
        };
        let mut queue: Vec<Vec<&str>> = adjacency
            .get(module.id())
            .map(|targets| {
                targets
                    .iter()
                    .map(|target| vec![module.id(), *target])
                    .collect()
            })
            .unwrap_or_default();
        while let Some(path) = queue.pop() {
            let last = *path.last().expect("queued paths are nonempty");
            let last_module = by_id.get(last).expect("queued ids are present");
            if ranks
                .get(last_module.stage())
                .is_some_and(|rank| *rank > *module_rank)
            {
                expected.insert(module.id().to_string());
                break;
            }
            if let Some(next_ids) = adjacency.get(last) {
                for next in next_ids {
                    if !path.contains(next) {
                        let mut extended = path.clone();
                        extended.push(next);
                        queue.push(extended);
                    }
                }
            }
        }
    }
    expected
}

// ─────────────────────────────────────────────────────────────────────────
// Observed diagnostics.
// ─────────────────────────────────────────────────────────────────────────

fn pass_tag(pass: DagValidationPass) -> Option<PassTag> {
    match pass {
        DagValidationPass::GlobalClaimConflicts => Some(PassTag::GlobalClaims),
        DagValidationPass::PerRegionClaimConflicts => Some(PassTag::PerRegionClaims),
        DagValidationPass::MissingDependencies => Some(PassTag::Missing),
        DagValidationPass::WriteConflicts => Some(PassTag::Write),
        DagValidationPass::CrossStageDependencyLegality => Some(PassTag::CrossStage),
        _ => None,
    }
}

fn scope_model(scope: &ConflictScope) -> ScopeModel {
    match scope {
        ConflictScope::Global => ScopeModel::Global,
        ConflictScope::Region {
            object_id,
            region_id,
            global_layer_index,
        } => ScopeModel::Region {
            object_id: object_id.clone(),
            region_id: region_id.clone(),
            layer: *global_layer_index,
        },
    }
}

fn observed_diagnostics(report: &DagValidationReport) -> BTreeSet<DiagKey> {
    report
        .errors
        .iter()
        .filter_map(|diagnostic| {
            let tag = pass_tag(diagnostic.pass)?;
            Some(match (&diagnostic.detail, tag) {
                (
                    SchedulerError::ClaimConflict {
                        claim,
                        module_a,
                        module_b,
                        scope,
                    },
                    PassTag::GlobalClaims | PassTag::PerRegionClaims,
                ) => DiagKey::Claim {
                    pass: tag,
                    claim: claim.clone(),
                    module_a: module_a.clone(),
                    module_b: module_b.clone(),
                    scope: scope_model(scope),
                },
                (SchedulerError::MissingDependency { module, requires }, PassTag::GlobalClaims)
                | (SchedulerError::MissingDependency { module, requires }, PassTag::Missing) => {
                    DiagKey::Missing {
                        pass: tag,
                        module: module.clone(),
                        requires: requires.clone(),
                    }
                }
                (
                    SchedulerError::WriteConflict {
                        field,
                        module_a,
                        module_b,
                        stage,
                        orderable,
                    },
                    PassTag::Write,
                ) => {
                    let (module_a, module_b) = lexical_pair(module_a.clone(), module_b.clone());
                    DiagKey::Write {
                        field: field.clone(),
                        module_a,
                        module_b,
                        stage: stage.clone(),
                        orderable: *orderable,
                    }
                }
                (
                    SchedulerError::CrossStageDependency {
                        module,
                        requires,
                        module_stage,
                        required_stage,
                    },
                    PassTag::CrossStage,
                ) => DiagKey::CrossStage {
                    module: module.clone(),
                    requires: requires.clone(),
                    module_stage: module_stage.clone(),
                    required_stage: required_stage.clone(),
                },
                (other, pass) => DiagKey::Unexpected {
                    pass,
                    detail: format!("{other:?}"),
                },
            })
        })
        .collect()
}

fn observed_transitive(
    report: &DagValidationReport,
) -> Vec<(ModuleId, String, String, Vec<ModuleId>)> {
    report
        .errors
        .iter()
        .filter_map(|diagnostic| match &diagnostic.detail {
            SchedulerError::TransitiveStageDependency {
                module,
                path,
                module_stage,
                later_stage,
            } if diagnostic.pass == DagValidationPass::TransitiveDependencyLegality => Some((
                module.clone(),
                module_stage.clone(),
                later_stage.clone(),
                path.clone(),
            )),
            _ => None,
        })
        .collect()
}

// ─────────────────────────────────────────────────────────────────────────
// Case strategies.
// ─────────────────────────────────────────────────────────────────────────

/// One tagged-mode strategy whose mode tag never shrinks, so a shrink keeps the
/// exact witness alive.
///
/// The mode source is a `sample::select(..).no_shrink()`: unlike a Proptest
/// `Union`, simplifying a case can never switch it into another mode's branch.
/// The selector witness is part of the mode tag for the same reason.
pub fn claim_case_strategy(limits: &ClaimLimits) -> BoxedStrategy<ClaimCase> {
    let limits = limits.clone();
    proptest::sample::select(available_modes(&limits))
        .no_shrink()
        .prop_flat_map(move |mode| mode_strategy(mode, &limits))
        .boxed()
}

fn mode_strategy(mode: ClaimMode, limits: &ClaimLimits) -> BoxedStrategy<ClaimCase> {
    match mode {
        ClaimMode::FillGlobalMultiplicity(claim) => {
            fill_case(mode, claim, FillRule::GlobalMultiplicity, limits)
        }
        ClaimMode::FillGlobalAbsent(claim) => {
            fill_case(mode, claim, FillRule::GlobalAbsent, limits)
        }
        ClaimMode::FillRegionDuplicate(claim) => {
            fill_case(mode, claim, FillRule::RegionDuplicate, limits)
        }
        ClaimMode::FamilyGlobalExempt(claim) => family_case(mode, claim, limits),
        ClaimMode::FamilySuffixNotExempt => family_suffix_case(limits),
        ClaimMode::OrdinaryGlobal => ordinary_case(limits),
        ClaimMode::RaftGlobal => raft_case(limits),
        ClaimMode::RegionScopes => region_scopes_case(limits),
        ClaimMode::DelimiterScopes => delimiter_case(limits),
        ClaimMode::WriteConflicts => write_case(limits),
        ClaimMode::MissingUniverse => missing_case(limits),
        ClaimMode::CrossStage => cross_stage_case(limits),
        ClaimMode::CrossStageSharedStage => cross_stage_shared_stage_case(limits),
        ClaimMode::DisabledUniverse => disabled_case(limits),
        ClaimMode::StableSameRegion(claim) => {
            stable_case(mode, claim, StableShape::SameRegionCrossLayer, limits)
        }
        ClaimMode::StableCrossRegion(claim) => {
            stable_case(mode, claim, StableShape::CrossRegionCrossLayer, limits)
        }
        ClaimMode::StableThreeHolders(claim) => stable_three_holders_case(claim, limits),
        ClaimMode::StableSameModuleAcrossLayers => stable_same_module_case(limits),
        ClaimMode::StableDistinctObjects => stable_distinct_objects_case(limits),
        ClaimMode::TransitionCapable(claim) => {
            stable_case(mode, claim, StableShape::SameRegionCrossLayer, limits)
        }
        ClaimMode::SelectionPairing(witness) => selection_pairing_case(witness, limits),
    }
}

#[derive(Debug, Clone, Copy)]
enum FillRule {
    GlobalMultiplicity,
    GlobalAbsent,
    RegionDuplicate,
}

fn fill_case(
    mode: ClaimMode,
    claim: &'static str,
    rule: FillRule,
    limits: &ClaimLimits,
) -> BoxedStrategy<ClaimCase> {
    uuid_text(limits)
        .prop_map(move |text| {
            let ids = module_ids(3, &text);
            let modules = plain_modules(&ids, STAGE_INFILL);
            let mut holders = fixed_fill_holders(&ids[0]);
            match rule {
                FillRule::GlobalMultiplicity => holders.push(global_holder(claim, &ids[1])),
                FillRule::GlobalAbsent => holders.retain(|holder| holder.claim != claim),
                FillRule::RegionDuplicate => {
                    holders.push(region_holder(claim, &ids[1], &text, "r0", Some(0)));
                    holders.push(region_holder(claim, &ids[2], &text, "r0", Some(0)));
                }
            }
            case(mode, modules, holders, vec![text])
        })
        .boxed()
}

fn family_case(
    mode: ClaimMode,
    claim: &'static str,
    limits: &ClaimLimits,
) -> BoxedStrategy<ClaimCase> {
    uuid_text(limits)
        .prop_map(move |text| {
            let ids = module_ids(3, &text);
            let modules = plain_modules(&ids, STAGE_INFILL);
            let mut holders = fixed_fill_holders(&ids[0]);
            holders.push(global_holder(claim, &ids[0]));
            holders.push(global_holder(claim, &ids[1]));
            case(mode, modules, holders, vec![text])
        })
        .boxed()
}

fn family_suffix_case(limits: &ClaimLimits) -> BoxedStrategy<ClaimCase> {
    (uuid_text(limits), raw_text(limits))
        .prop_map(|(text, suffix)| {
            let ids = module_ids(3, &text);
            let modules = plain_modules(&ids, STAGE_INFILL);
            let mut holders = fixed_fill_holders(&ids[0]);
            let claim = format!("support-family:{suffix}");
            holders.push(global_holder(&claim, &ids[0]));
            holders.push(global_holder(&claim, &ids[1]));
            case(
                ClaimMode::FamilySuffixNotExempt,
                modules,
                holders,
                vec![text, suffix],
            )
        })
        .boxed()
}

fn ordinary_case(limits: &ClaimLimits) -> BoxedStrategy<ClaimCase> {
    let observations = usize_bound(limits.max_observations);
    let holder_count = if observations >= 3 { 3 } else { 2 };
    let module_count = usize_bound(limits.max_modules).min(holder_count + 2).max(3);

    uuid_text(limits)
        .prop_map(move |text| {
            let ids = module_ids(module_count, &text);
            let modules = plain_modules(&ids, STAGE_INFILL);
            let mut holders = fixed_fill_holders(&ids[0]);
            for module in ids.iter().take(holder_count) {
                holders.push(global_holder(ORDINARY_CLAIM, module));
            }
            if observations > holder_count {
                // A repeated observation of the same holder must not add pairs.
                holders.push(global_holder(ORDINARY_CLAIM, &ids[0]));
            }
            case(ClaimMode::OrdinaryGlobal, modules, holders, vec![text])
        })
        .boxed()
}

fn raft_case(limits: &ClaimLimits) -> BoxedStrategy<ClaimCase> {
    uuid_text(limits)
        .prop_map(|text| {
            let ids = module_ids(3, &text);
            let modules = plain_modules(&ids, STAGE_INFILL);
            let mut holders = fixed_fill_holders(&ids[0]);
            holders.push(global_holder(RAFT_CLAIM, &ids[0]));
            holders.push(global_holder(RAFT_CLAIM, &ids[1]));
            case(ClaimMode::RaftGlobal, modules, holders, vec![text])
        })
        .boxed()
}

fn region_scopes_case(limits: &ClaimLimits) -> BoxedStrategy<ClaimCase> {
    let observations = usize_bound(limits.max_observations);
    let claim_cap = usize_bound(limits.max_claims);
    let claims_max = (observations / 2).clamp(1, claim_cap.max(1));

    (uuid_text(limits), 1usize..=claims_max)
        .prop_map(move |(text, claim_count)| {
            let ids = module_ids(3, &text);
            let modules = plain_modules(&ids, STAGE_INFILL);
            let mut holders = fixed_fill_holders(&ids[0]);
            for index in 0..claim_count {
                let claim = format!("claim:region-{index}");
                holders.push(region_holder(&claim, &ids[0], &text, "r0", Some(0)));
                holders.push(region_holder(&claim, &ids[1], &text, "r0", Some(0)));
            }
            if observations > 2 * claim_count {
                // A different typed scope of the same object stays independent.
                holders.push(region_holder(
                    "claim:region-0",
                    &ids[2],
                    &text,
                    "r1",
                    Some(0),
                ));
            }
            case(ClaimMode::RegionScopes, modules, holders, vec![text])
        })
        .boxed()
}

fn delimiter_case(limits: &ClaimLimits) -> BoxedStrategy<ClaimCase> {
    let observations = usize_bound(limits.max_observations);
    (
        uuid_text(limits),
        raw_text(limits),
        raw_text(limits),
        raw_text(limits),
    )
        .prop_map(move |(text, first, second, third)| {
            let ids = module_ids(3, &text);
            let modules = plain_modules(&ids, STAGE_INFILL);
            let mut holders = fixed_fill_holders(&ids[0]);
            let object_a = format!("{first}:{second}");
            let region_a = third.clone();
            let object_b = first.clone();
            let region_b = format!("{second}:{third}");
            holders.push(region_holder(
                ORDINARY_CLAIM,
                &ids[0],
                &object_a,
                &region_a,
                Some(0),
            ));
            holders.push(region_holder(
                ORDINARY_CLAIM,
                &ids[1],
                &object_b,
                &region_b,
                Some(0),
            ));
            if observations >= 3 {
                holders.push(region_holder(
                    ORDINARY_CLAIM,
                    &ids[2],
                    &object_a,
                    &region_a,
                    Some(0),
                ));
            }
            case(
                ClaimMode::DelimiterScopes,
                modules,
                holders,
                vec![text, first, second, third],
            )
        })
        .boxed()
}

fn write_case(limits: &ClaimLimits) -> BoxedStrategy<ClaimCase> {
    // Two distinct support claims are the natural family-write witness, but a
    // profile may accept only one variable claim. In that case both modules
    // declare the same family-support claim, which keeps the family-orderable
    // write rules in play without exceeding the accepted `max_claims`.
    let claim_budget = usize_bound(limits.max_claims);
    let (first_claim, second_claim) = if claim_budget >= 2 {
        ("support-generator", "support-planner")
    } else {
        ("support-generator", "support-generator")
    };

    (uuid_text(limits), permutations(3))
        .prop_map(move |(text, order)| {
            let ids = module_ids(3, &text);
            let shared_writes: Vec<String> = [
                "SupportIR",
                "SupportIRx",
                "SupportPlanIR.regions",
                "MeshIR.layers",
                "MeshIR.regions",
            ]
            .iter()
            .map(|field| (*field).to_string())
            .collect();

            let modules = vec![
                module_with(
                    &ids[0],
                    STAGE_INFILL,
                    vec![String::from(first_claim)],
                    Vec::new(),
                    shared_writes.clone(),
                    Vec::new(),
                    Vec::new(),
                ),
                module_with(
                    &ids[1],
                    STAGE_INFILL,
                    vec![String::from(second_claim)],
                    vec![String::from("MeshIR.layers")],
                    shared_writes,
                    Vec::new(),
                    Vec::new(),
                ),
                module_with(
                    &ids[2],
                    STAGE_INFILL,
                    Vec::new(),
                    Vec::new(),
                    vec![String::from("MeshIR.layers")],
                    vec![ids[0].clone()],
                    Vec::new(),
                ),
            ];

            let mut holders = fixed_fill_holders(&ids[0]);
            holders.push(global_holder(first_claim, &ids[0]));
            holders.push(global_holder(second_claim, &ids[1]));

            let dag = single_stage_dag(&modules, STAGE_INFILL);
            let nodes = order
                .iter()
                .map(|index| dag.nodes[*index].clone())
                .collect();
            ClaimCase {
                mode: ClaimMode::WriteConflicts,
                modules,
                stage_dags: vec![StageDag {
                    stage: dag.stage,
                    nodes,
                }],
                claim_holders: holders,
                disabled: Vec::new(),
                variable_text: vec![text],
            }
        })
        .boxed()
}

fn missing_case(limits: &ClaimLimits) -> BoxedStrategy<ClaimCase> {
    (uuid_text(limits), uuid_text(limits))
        .prop_map(|(text, absent_text)| {
            let ids = module_ids(3, &text);
            let absent_module = format!("com.pbt.absent-{absent_text}");
            let absent_claim = format!("claim:absent-{absent_text}");
            let modules = vec![
                module_with(
                    &ids[0],
                    STAGE_INFILL,
                    Vec::new(),
                    Vec::new(),
                    Vec::new(),
                    vec![absent_module],
                    vec![absent_claim],
                ),
                plain_module(&ids[1], STAGE_INFILL),
                plain_module(&ids[2], STAGE_INFILL),
            ];
            let holders = fixed_fill_holders(&ids[0]);
            case(
                ClaimMode::MissingUniverse,
                modules,
                holders,
                vec![text, absent_text],
            )
        })
        .boxed()
}

fn cross_stage_case(limits: &ClaimLimits) -> BoxedStrategy<ClaimCase> {
    uuid_text(limits)
        .prop_map(|text| {
            let ids = module_ids(3, &text);
            let modules = vec![
                module_with(
                    &ids[0],
                    STAGE_MESH_ANALYSIS,
                    Vec::new(),
                    Vec::new(),
                    Vec::new(),
                    vec![ids[1].clone()],
                    Vec::new(),
                ),
                module_with(
                    &ids[1],
                    STAGE_LAYER_PLANNING,
                    Vec::new(),
                    Vec::new(),
                    Vec::new(),
                    vec![ids[2].clone()],
                    Vec::new(),
                ),
                plain_module(&ids[2], STAGE_GCODE_EMIT),
            ];
            let holders = fixed_fill_holders(&ids[0]);
            case(ClaimMode::CrossStage, modules, holders, vec![text])
        })
        .boxed()
}

/// Transitive-only cross-stage witness: A and B share `PrePass::LayerPlanning`,
/// B requires C in `PostPass::GCodeEmit`, and A requires only B. Every module
/// that violates the *transitive* rule here has no direct violation, which is
/// exactly the shape a direct-only pass would falsely accept.
fn cross_stage_shared_stage_case(limits: &ClaimLimits) -> BoxedStrategy<ClaimCase> {
    uuid_text(limits)
        .prop_map(|text| {
            let ids = module_ids(3, &text);
            let modules = vec![
                module_with(
                    &ids[0],
                    STAGE_LAYER_PLANNING,
                    Vec::new(),
                    Vec::new(),
                    Vec::new(),
                    vec![ids[1].clone()],
                    Vec::new(),
                ),
                module_with(
                    &ids[1],
                    STAGE_LAYER_PLANNING,
                    Vec::new(),
                    Vec::new(),
                    Vec::new(),
                    vec![ids[2].clone()],
                    Vec::new(),
                ),
                plain_module(&ids[2], STAGE_GCODE_EMIT),
            ];
            let holders = fixed_fill_holders(&ids[0]);
            case(
                ClaimMode::CrossStageSharedStage,
                modules,
                holders,
                vec![text],
            )
        })
        .boxed()
}

fn disabled_case(limits: &ClaimLimits) -> BoxedStrategy<ClaimCase> {
    let observations = usize_bound(limits.max_observations);
    let claim_budget = usize_bound(limits.max_claims);
    let ordinary_conflict = observations >= 3 && claim_budget >= 2;
    uuid_text(limits)
        .prop_map(move |text| {
            let ids = module_ids(3, &text);
            let modules = vec![
                module_with(
                    &ids[0],
                    STAGE_INFILL,
                    Vec::new(),
                    Vec::new(),
                    Vec::new(),
                    vec![ids[1].clone()],
                    vec![String::from(CAPABILITY_CLAIM)],
                ),
                plain_module(&ids[1], STAGE_INFILL),
                plain_module(&ids[2], STAGE_INFILL),
            ];
            // The fixed fill setup is held by a surviving module so removing the
            // disabled module cannot look like an unrelated fill gap.
            let mut holders = fixed_fill_holders(&ids[2]);
            holders.push(global_holder(CAPABILITY_CLAIM, &ids[1]));
            if ordinary_conflict {
                holders.push(global_holder(ORDINARY_CLAIM, &ids[1]));
                holders.push(global_holder(ORDINARY_CLAIM, &ids[2]));
            }
            case(ClaimMode::DisabledUniverse, modules, holders, vec![text])
                .with_disabled(vec![ids[1].clone()])
        })
        .boxed()
}

#[derive(Debug, Clone, Copy)]
enum StableShape {
    SameRegionCrossLayer,
    CrossRegionCrossLayer,
}

fn stable_case(
    mode: ClaimMode,
    claim: &'static str,
    shape: StableShape,
    limits: &ClaimLimits,
) -> BoxedStrategy<ClaimCase> {
    let max_layers = u32_bound(limits.max_layers);
    (uuid_text(limits), 0u32..max_layers)
        .prop_map(move |(text, raw_layer)| {
            let (first, second) = two_layers(raw_layer, max_layers);
            let ids = module_ids(3, &text);
            let modules = plain_modules(&ids, STAGE_INFILL);
            let mut holders = fixed_fill_holders(&ids[0]);
            let right_region = match shape {
                StableShape::SameRegionCrossLayer => "r0",
                StableShape::CrossRegionCrossLayer => "r1",
            };
            holders.push(region_holder(claim, &ids[0], &text, "r0", Some(first)));
            holders.push(region_holder(
                claim,
                &ids[1],
                &text,
                right_region,
                Some(second),
            ));
            case(mode, modules, holders, vec![text])
        })
        .boxed()
}

/// Three distinct stable-claim holders in three regions and different layers of
/// one object. Production reports each conflicting pair inside the first
/// holder's own region; a model that computes one group-wide region would
/// mis-report the `(second, third)` pair.
fn stable_three_holders_case(
    claim: &'static str,
    limits: &ClaimLimits,
) -> BoxedStrategy<ClaimCase> {
    let max_layers = u32_bound(limits.max_layers);
    (uuid_text(limits), 0u32..max_layers)
        .prop_map(move |(text, raw_layer)| {
            let first_layer = raw_layer % max_layers;
            let ids = module_ids(3, &text);
            let modules = plain_modules(&ids, STAGE_INFILL);
            let mut holders = fixed_fill_holders(&ids[0]);
            for (index, region) in ["r0", "r1", "r2"].into_iter().enumerate() {
                let offset = u32::try_from(index).expect("three holders fit u32");
                let layer = (first_layer + offset) % max_layers;
                holders.push(region_holder(
                    claim,
                    &ids[index],
                    &text,
                    region,
                    Some(layer),
                ));
            }
            case(
                ClaimMode::StableThreeHolders(claim),
                modules,
                holders,
                vec![text],
            )
        })
        .boxed()
}

fn stable_same_module_case(limits: &ClaimLimits) -> BoxedStrategy<ClaimCase> {
    let max_layers = u32_bound(limits.max_layers);
    (uuid_text(limits), 0u32..max_layers)
        .prop_map(move |(text, raw_layer)| {
            let (first, second) = two_layers(raw_layer, max_layers);
            let ids = module_ids(3, &text);
            let modules = plain_modules(&ids, STAGE_INFILL);
            let mut holders = fixed_fill_holders(&ids[0]);
            for layer in [first, second] {
                holders.push(region_holder(
                    STABLE_CLAIM_IDS[0],
                    &ids[0],
                    &text,
                    "r0",
                    Some(layer),
                ));
            }
            case(
                ClaimMode::StableSameModuleAcrossLayers,
                modules,
                holders,
                vec![text],
            )
        })
        .boxed()
}

fn stable_distinct_objects_case(limits: &ClaimLimits) -> BoxedStrategy<ClaimCase> {
    let max_layers = u32_bound(limits.max_layers);
    (uuid_text(limits), uuid_text(limits), 0u32..max_layers)
        .prop_map(move |(left, right, raw_layer)| {
            let (left, right) = ensure_distinct(left, right);
            let (first, second) = two_layers(raw_layer, max_layers);
            let ids = module_ids(3, &left);
            let modules = plain_modules(&ids, STAGE_INFILL);
            let mut holders = fixed_fill_holders(&ids[0]);
            holders.push(region_holder(
                STABLE_CLAIM_IDS[0],
                &ids[0],
                &left,
                "r0",
                Some(first),
            ));
            holders.push(region_holder(
                STABLE_CLAIM_IDS[0],
                &ids[1],
                &right,
                "r0",
                Some(second),
            ));
            case(
                ClaimMode::StableDistinctObjects,
                modules,
                holders,
                vec![left, right],
            )
        })
        .boxed()
}

// ─────────────────────────────────────────────────────────────────────────
// Declarative selection/pairing domain.
// ─────────────────────────────────────────────────────────────────────────

/// One group of declarative modules added whole while the accepted module and
/// claim budgets allow it.
///
/// The order is the priority: the typed `perimeter-generator` selector pair is
/// always present; then the fill/support renderer, the second family renderer,
/// the family-scoped planner and finally the ordinary contested pair. A narrow
/// profile gets a faithful subset (the model is recomputed from the subset),
/// and the packet's full ceilings get every FIX-1 element.
const SELECTION_GROUPS: &[&[(&str, &[&str])]] = &[
    // Two typed perimeter candidates in one stage.
    &[
        ("com.core.classic-perimeters", &["perimeter-generator"]),
        ("com.core.arachne-perimeters", &["perimeter-generator"]),
    ],
    // Fill retention + a traditional-family renderer. The module is `com.core.*`
    // so the configured-holder record can use both the full id and the short
    // name.
    &[(
        "com.core.fill-all",
        &[
            "claim:top-fill",
            "claim:bottom-fill",
            "claim:bridge-fill",
            "claim:sparse-fill",
            "support-generator",
            "support-family:traditional",
        ],
    )],
    // A second family renderer makes the pairing incomplete:
    // `missing_planners = ["tree"]`.
    &[(
        "com.pbt.claim-tree-renderer",
        &["support-generator", "support-family:tree"],
    )],
    // A family-scoped planner is retained per family (never deduplicated).
    &[(
        "com.pbt.claim-traditional-planner",
        &["support-planner", "support-family:traditional"],
    )],
    // Two non-family planners sharing one ordinary contested claim: the lexical
    // first wins both, the other drops with one named diagnostic.
    &[
        (
            "com.pbt.claim-planner-0",
            &["claim:infill-link", "support-planner"],
        ),
        (
            "com.pbt.claim-planner-1",
            &["claim:infill-link", "support-planner"],
        ),
    ],
];

/// The selection domain the accepted bounds can carry, in declarative order.
fn selection_modules(limits: &ClaimLimits) -> Vec<(&'static str, Vec<&'static str>)> {
    let mut selected: BTreeSet<&'static str> = FILL_CLAIM_IDS.iter().copied().collect();
    let mut chosen: Vec<(&'static str, Vec<&'static str>)> = Vec::new();
    for group in SELECTION_GROUPS {
        let mut added: BTreeSet<&'static str> = BTreeSet::new();
        for entry in group.iter() {
            for claim in entry.1.iter() {
                if !selected.contains(*claim) {
                    added.insert(*claim);
                }
            }
        }
        let modules_after = chosen.len() + group.len();
        let variable_claims_after = selected.len() + added.len() - FILL_CLAIM_IDS.len();
        if u64::try_from(modules_after).unwrap_or(u64::MAX) > limits.max_modules
            || u64::try_from(variable_claims_after).unwrap_or(u64::MAX) > limits.max_claims
        {
            continue;
        }
        selected.extend(added);
        chosen.extend(group.iter().map(|entry| (entry.0, entry.1.to_vec())));
    }
    chosen
}

fn selection_pairing_case(
    witness: SelectionWitness,
    limits: &ClaimLimits,
) -> BoxedStrategy<ClaimCase> {
    let domain = selection_modules(limits);
    assert!(
        !domain.is_empty(),
        "every accepted H-CLAIMS profile must fit at least the perimeter pair"
    );
    let module_count = domain.len();
    let fill_holder = domain
        .iter()
        .find(|entry| entry.0 == "com.core.fill-all")
        .map_or_else(|| domain[0].0, |entry| entry.0);
    let fill_holders = fixed_fill_holders(fill_holder);

    (0..module_count)
        .prop_map(move |rotation| {
            // Rotating the declaration order is a real generative dimension: the
            // dedup sorts by module id, so the kept set and every diagnostic must
            // be order-insensitive, while a shrink towards 0 cannot erase the
            // selector witness.
            let mut ordered = domain.clone();
            ordered.rotate_left(rotation);
            let modules = ordered
                .into_iter()
                .map(|(id, claims)| {
                    module_with(
                        id,
                        STAGE_INFILL,
                        claims.into_iter().map(String::from).collect(),
                        Vec::new(),
                        Vec::new(),
                        Vec::new(),
                        Vec::new(),
                    )
                })
                .collect();
            case(
                ClaimMode::SelectionPairing(witness),
                modules,
                fill_holders.clone(),
                Vec::new(),
            )
        })
        .boxed()
}

fn case(
    mode: ClaimMode,
    modules: Vec<LoadedModule>,
    claim_holders: Vec<ClaimHolder>,
    variable_text: Vec<String>,
) -> ClaimCase {
    let stage_dags = stage_dags_for(&modules);
    ClaimCase {
        mode,
        modules,
        stage_dags,
        claim_holders,
        disabled: Vec::new(),
        variable_text,
    }
}

impl ClaimCase {
    fn with_disabled(mut self, disabled: Vec<ModuleId>) -> Self {
        self.disabled = disabled;
        self
    }
}

// ─────────────────────────────────────────────────────────────────────────
// Checks.
// ─────────────────────────────────────────────────────────────────────────

/// Run every modeled check for one generated case.
pub fn check_claim_case(case: &ClaimCase, limits: &ClaimLimits) -> Result<(), TestCaseError> {
    assert_fill_catalog()?;
    assert_fixed_fill_setup(case)?;
    assert_generated_case_within_limits(case, limits)?;
    if case.mode == ClaimMode::DelimiterScopes {
        assert_delimiter_witness(case)?;
    }

    if let ClaimMode::SelectionPairing(witness) = case.mode {
        // The selection/pairing seam has its own falsifiable oracle: it drives
        // three real scheduler functions against the declarative selector table,
        // and deliberately does not compare a `validate_startup_dag` diagnostic
        // set (that surface is covered by the other modes).
        return check_selection_case(case, witness, limits);
    }

    let report = validate_startup_dag(&case.build_request());
    let expected = expected_diagnostics(case);
    let observed = observed_diagnostics(&report);
    prop_assert_eq!(
        &observed,
        &expected,
        "covered-pass diagnostics disagree with the typed model for {:?}: {}",
        case.mode,
        describe_case(case)
    );

    assert_transitive(case, &report)?;
    if case.mode == ClaimMode::CrossStageSharedStage {
        assert_shared_stage_transitive_witness(case, &report)?;
    }
    if case.mode == ClaimMode::DisabledUniverse {
        assert_disabled_boundary(case)?;
    }
    Ok(())
}

/// Every generated case must fit the bounds the profile accepted.
///
/// The fixed four-role fill setup is additional budget, exactly as the packet
/// describes observation budget, so it is excluded from the variable-claim and
/// observation budgets; it is still counted for claim *presence* by
/// `assert_fixed_fill_setup`.
fn assert_generated_case_within_limits(
    case: &ClaimCase,
    limits: &ClaimLimits,
) -> Result<(), TestCaseError> {
    let module_count = u64::try_from(case.modules.len()).expect("module count fits u64");
    prop_assert!(
        module_count <= limits.max_modules,
        "case {:?} generated {module_count} modules above max_modules {}",
        case.mode,
        limits.max_modules
    );

    let variable_claims = case.variable_claim_ids();
    let claim_count = u64::try_from(variable_claims.len()).expect("claim count fits u64");
    prop_assert!(
        claim_count <= limits.max_claims,
        "case {:?} generated {claim_count} distinct variable claims {:?} above max_claims {}",
        case.mode,
        variable_claims,
        limits.max_claims
    );

    let observation_count = u64::try_from(case.claim_holders.len()).expect("count fits u64");
    let observation_budget =
        limits.max_observations + u64::try_from(FILL_CLAIM_IDS.len()).expect("four fills fit u64");
    prop_assert!(
        observation_count <= observation_budget,
        "case {:?} generated {observation_count} observations above max_observations {} \
         plus the fixed four-role fill setup",
        case.mode,
        limits.max_observations
    );

    let mut layers = BTreeSet::new();
    for holder in &case.claim_holders {
        if let ConflictScope::Region {
            global_layer_index: Some(layer),
            ..
        } = &holder.scope
        {
            layers.insert(*layer);
        }
    }
    let layer_count = u64::try_from(layers.len()).expect("layer count fits u64");
    prop_assert!(
        layer_count <= limits.max_layers,
        "case {:?} used {layer_count} distinct layers above max_layers {}",
        case.mode,
        limits.max_layers
    );
    for layer in &layers {
        prop_assert!(
            u64::from(*layer) < limits.max_layers,
            "case {:?} used layer {layer} outside the accepted max_layers {}",
            case.mode,
            limits.max_layers
        );
    }

    for text in &case.variable_text {
        let uuid = is_uuid_syntax(text);
        let floor = if uuid { 36 } else { 8 };
        prop_assert!(
            text.len() >= floor,
            "case {:?} generated variable id {text:?} shorter than the {floor}-byte floor",
            case.mode
        );
        let length = u64::try_from(text.len()).expect("text length fits u64");
        prop_assert!(
            length <= limits.max_text_bytes,
            "case {:?} generated variable id {text:?} of {length} bytes above max_text_bytes {}",
            case.mode,
            limits.max_text_bytes
        );
    }
    Ok(())
}

/// Whether `text` is exactly the 36-byte UUID shape the object-id domain emits.
fn is_uuid_syntax(text: &str) -> bool {
    let bytes = text.as_bytes();
    bytes.len() == 36
        && bytes.iter().enumerate().all(|(index, byte)| {
            if [8, 13, 18, 23].contains(&index) {
                *byte == b'-'
            } else {
                byte.is_ascii_digit() || (b'a'..=b'f').contains(byte)
            }
        })
}

fn assert_fill_catalog() -> Result<(), TestCaseError> {
    let mut production: Vec<&str> = FILL_CLAIM_IDS.to_vec();
    production.sort_unstable();
    let mut documented: Vec<&str> = EXPECTED_FILL_CLAIM_IDS.to_vec();
    documented.sort_unstable();
    prop_assert_eq!(
        production,
        documented,
        "FILL_CLAIM_IDS must be exactly the four documented configured fill ids"
    );
    Ok(())
}

fn assert_fixed_fill_setup(case: &ClaimCase) -> Result<(), TestCaseError> {
    let holders = case.enabled_holders();
    for fill in FILL_CLAIM_IDS {
        let deliberately_absent =
            matches!(case.mode, ClaimMode::FillGlobalAbsent(claim) if claim == *fill);
        if deliberately_absent {
            continue;
        }
        prop_assert!(
            holders.iter().any(|holder| holder.claim == *fill),
            "the fixed global fill setup lost {fill} in mode {:?}; an unrelated fill \
             error must never be able to make a rejection look correct",
            case.mode
        );
    }
    Ok(())
}

fn assert_delimiter_witness(case: &ClaimCase) -> Result<(), TestCaseError> {
    let holders = case.enabled_holders();
    let observations: Vec<&ClaimHolder> = holders
        .iter()
        .filter(|holder| holder.claim == ORDINARY_CLAIM)
        .collect();
    prop_assert!(
        observations.len() >= 2,
        "the delimiter mode must hold two scoped observations"
    );

    let mut scopes: Vec<(String, String, Option<u32>)> = Vec::new();
    for holder in observations {
        match &holder.scope {
            ConflictScope::Region {
                object_id,
                region_id,
                global_layer_index,
            } => scopes.push((object_id.clone(), region_id.clone(), *global_layer_index)),
            ConflictScope::Global => {
                prop_assert!(false, "the delimiter mode must use region scopes only");
            }
        }
    }
    let first = scopes[0].clone();
    let other = scopes
        .iter()
        .find(|scope| **scope != first)
        .cloned()
        .expect("the delimiter mode must create two distinct typed scopes");

    prop_assert_ne!(
        &first,
        &other,
        "distinct typed (object, region, layer) tuples must not be equal"
    );
    let legacy_first = legacy_scope_key(&first);
    let legacy_other = legacy_scope_key(&other);
    prop_assert_eq!(
        legacy_first,
        legacy_other,
        "the delimiter witness must collide under the previous concatenated string key"
    );
    Ok(())
}

fn legacy_scope_key(scope: &(String, String, Option<u32>)) -> String {
    format!(
        "region:{}:{}:{}",
        scope.0,
        scope.1,
        scope
            .2
            .map_or_else(|| String::from("none"), |layer| layer.to_string())
    )
}

fn assert_transitive(case: &ClaimCase, report: &DagValidationReport) -> Result<(), TestCaseError> {
    let modules = case.enabled_modules();
    let ranks = stage_ranks();
    let by_id: BTreeMap<&str, &LoadedModule> =
        modules.iter().map(|module| (module.id(), module)).collect();
    let expected_modules = expected_transitive_modules(&modules);
    let observed = observed_transitive(report);

    let mut observed_modules = BTreeSet::new();
    for (module, module_stage, later_stage, path) in &observed {
        prop_assert!(
            observed_modules.insert(module.clone()),
            "{module} received more than one TransitiveStageDependency"
        );

        let Some(module_info) = by_id.get(module.as_str()) else {
            return Err(TestCaseError::fail(format!(
                "transitive diagnostic names unknown module {module}"
            )));
        };
        prop_assert_eq!(
            module_stage.as_str(),
            module_info.stage(),
            "transitive diagnostic reported the wrong requesting stage for {}",
            module
        );
        prop_assert_eq!(
            path.first().map(String::as_str),
            Some(module.as_str()),
            "transitive path must start at the requesting module"
        );
        prop_assert!(
            path.len() >= 2,
            "transitive path must contain at least the requesting and one required module"
        );

        let mut distinct = BTreeSet::new();
        for node in path {
            prop_assert!(
                distinct.insert(node.clone()),
                "transitive path must be a simple path; {node} repeats in {path:?}"
            );
        }
        for pair in path.windows(2) {
            let Some(source) = by_id.get(pair[0].as_str()) else {
                return Err(TestCaseError::fail(format!(
                    "transitive path names unknown module {}",
                    pair[0]
                )));
            };
            prop_assert!(
                source
                    .requires_modules()
                    .iter()
                    .any(|required| required == &pair[1]),
                "transitive path edge {} -> {} is not a declared requires_modules edge",
                pair[0],
                pair[1]
            );
        }

        let last = path.last().expect("nonempty path");
        let last_module = by_id
            .get(last.as_str())
            .expect("every path node is in the effective universe");
        prop_assert_eq!(
            later_stage.as_str(),
            last_module.stage(),
            "later_stage must be the stage of the path's last module"
        );
        let module_rank = ranks
            .get(module_info.stage())
            .expect("generated stages are canonical");
        let later_rank = ranks
            .get(last_module.stage())
            .expect("generated stages are canonical");
        prop_assert!(
            later_rank > module_rank,
            "the transitive path must end at a strictly later stage"
        );
    }

    prop_assert_eq!(
        observed_modules,
        expected_modules,
        "transitive diagnostics must appear exactly for modules with a real \
         requires_modules path to a later stage; {}",
        describe_case(case)
    );
    Ok(())
}

/// The transitive-only witness: A and B share a stage, B requires C in a later
/// stage, and A requires only B. A direct-only rule would accept A silently.
fn assert_shared_stage_transitive_witness(
    case: &ClaimCase,
    report: &DagValidationReport,
) -> Result<(), TestCaseError> {
    let modules = case.enabled_modules();
    prop_assert_eq!(modules.len(), 3, "the witness is exactly three modules");
    let by_id: BTreeMap<&str, &LoadedModule> =
        modules.iter().map(|module| (module.id(), module)).collect();
    let ids: Vec<&str> = modules.iter().map(LoadedModule::id).collect();
    let (left, middle, right) = (ids[0], ids[1], ids[2]);

    let left_module = by_id.get(left).expect("witness module");
    let middle_module = by_id.get(middle).expect("witness module");
    let right_module = by_id.get(right).expect("witness module");

    // Premises: the witness really is transitive-only.
    prop_assert_eq!(
        left_module.stage(),
        middle_module.stage(),
        "A and B must share one stage or A would also violate the direct rule"
    );
    prop_assert!(
        stage_ranks()
            .get(right_module.stage())
            .is_some_and(|rank| *rank > stage_ranks()[middle_module.stage()]),
        "C must be in a strictly later stage than B"
    );
    prop_assert!(
        left_module
            .requires_modules()
            .iter()
            .any(|required| required == middle),
        "A must require B"
    );
    prop_assert!(
        !left_module
            .requires_modules()
            .iter()
            .any(|required| required == right),
        "A must not require C directly, or this would not be a transitive-only witness"
    );

    // The direct pass rejects only B -> C.
    let direct: Vec<&SchedulerError> = report
        .errors
        .iter()
        .filter(|diagnostic| diagnostic.pass == DagValidationPass::CrossStageDependencyLegality)
        .map(|diagnostic| &diagnostic.detail)
        .collect();
    prop_assert_eq!(
        direct.len(),
        1,
        "exactly one direct cross-stage dependency exists (B -> C), got {:?}",
        direct
    );
    prop_assert!(
        matches!(
            direct[0],
            SchedulerError::CrossStageDependency { module, requires, .. }
                if module == middle && requires == right
        ),
        "the direct diagnostic must be B -> C, got {:?}",
        direct[0]
    );

    // The transitive pass reports the three-node path for A and the two-node
    // path for B; the route is fully determined by this chain, so the exact
    // paths are part of the contract.
    let transitive = observed_transitive(report);
    let left_paths: Vec<&Vec<ModuleId>> = transitive
        .iter()
        .filter(|entry| entry.0 == left)
        .map(|entry| &entry.3)
        .collect();
    let middle_paths: Vec<&Vec<ModuleId>> = transitive
        .iter()
        .filter(|entry| entry.0 == middle)
        .map(|entry| &entry.3)
        .collect();
    prop_assert_eq!(
        left_paths.len(),
        1,
        "A must receive exactly one TransitiveStageDependency, got {:?}",
        transitive
    );
    prop_assert_eq!(
        left_paths[0],
        &vec![left.to_string(), middle.to_string(), right.to_string()],
        "A's transitive path must be the exact three-node [A, B, C] chain"
    );
    prop_assert_eq!(
        middle_paths.len(),
        1,
        "B must receive exactly one TransitiveStageDependency, got {:?}",
        transitive
    );
    prop_assert_eq!(
        middle_paths[0],
        &vec![middle.to_string(), right.to_string()],
        "B's transitive path must be the exact [B, C] chain"
    );
    for (module, _, later_stage, path) in &transitive {
        prop_assert_eq!(
            later_stage.as_str(),
            right_module.stage(),
            "every transitive path in this witness ends at C's later stage ({} -> {:?})",
            module,
            path
        );
    }
    Ok(())
}

fn assert_disabled_boundary(case: &ClaimCase) -> Result<(), TestCaseError> {
    let filtered = validate_startup_dag(&case.build_request());
    let unfiltered = validate_startup_dag(&case.unfiltered_request());

    let filtered_claims: Vec<&SchedulerError> = filtered
        .errors
        .iter()
        .filter(|diagnostic| {
            diagnostic.pass == DagValidationPass::PerRegionClaimConflicts
                || diagnostic.pass == DagValidationPass::GlobalClaimConflicts
        })
        .map(|diagnostic| &diagnostic.detail)
        .collect();
    prop_assert!(
        filtered_claims.is_empty(),
        "removing the disabled competing holder must eliminate its conflict, got {filtered_claims:?}"
    );

    let retained_missing: BTreeSet<(String, String)> = filtered
        .errors
        .iter()
        .filter(|diagnostic| diagnostic.pass == DagValidationPass::MissingDependencies)
        .filter_map(|diagnostic| match &diagnostic.detail {
            SchedulerError::MissingDependency { module, requires } => {
                Some((module.clone(), requires.clone()))
            }
            _ => None,
        })
        .collect();
    prop_assert_eq!(
        retained_missing.len(),
        2,
        "the retained consumer must reject the removed module and capability; got {:?}",
        retained_missing
    );

    let unfiltered_missing = unfiltered
        .errors
        .iter()
        .any(|diagnostic| diagnostic.pass == DagValidationPass::MissingDependencies);
    prop_assert!(
        !unfiltered_missing,
        "the unfiltered universe satisfies the consumer, so the disabled removal is what rejects it"
    );

    let unfiltered_claims = unfiltered
        .errors
        .iter()
        .filter(|diagnostic| {
            diagnostic.pass == DagValidationPass::GlobalClaimConflicts
                || diagnostic.pass == DagValidationPass::PerRegionClaimConflicts
        })
        .count();
    if case
        .enabled_holders()
        .iter()
        .any(|holder| holder.claim == ORDINARY_CLAIM)
    {
        prop_assert_eq!(
            unfiltered_claims,
            1,
            "exactly the removed competitor's conflict must exist before filtering"
        );
    }
    Ok(())
}

// ─────────────────────────────────────────────────────────────────────────
// Selection / pairing seam model.
// ─────────────────────────────────────────────────────────────────────────

/// One expected dropped module and the claim/winner its diagnostic must name.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SelectionDrop {
    /// Dropped module.
    pub module: ModuleId,
    /// Stage that owned the contested claim.
    pub stage: String,
    /// The first claim (in declaration order) the module lost.
    pub claim: String,
    /// The winning module named in the diagnostic.
    pub winner: ModuleId,
}

/// Independent selector-table expectation for the selection/pairing mode.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SelectionExpectation {
    /// Module ids production must keep, in lexical order.
    pub kept: Vec<ModuleId>,
    /// Drop diagnostics production must emit, in lexical module order.
    pub drops: Vec<SelectionDrop>,
    /// Families with a planner but no renderer.
    pub missing_renderers: Vec<String>,
    /// Families with a renderer but no planner.
    pub missing_planners: Vec<String>,
}

/// The configured `FillHolders` record, spelled out so the model re-derives the
/// holder-matching rule instead of calling the production matcher.
struct SelectionFillHolders {
    top: String,
    bottom: String,
    bridge: String,
    sparse: String,
}

impl SelectionFillHolders {
    fn holder_for(&self, claim: &str) -> Option<&str> {
        match claim {
            "claim:top-fill" => Some(&self.top),
            "claim:bottom-fill" => Some(&self.bottom),
            "claim:bridge-fill" => Some(&self.bridge),
            "claim:sparse-fill" => Some(&self.sparse),
            _ => None,
        }
    }

    /// The documented holder rule: exact full id, or the `com.core.` short form.
    fn matches(module_id: &str, holder: &str) -> bool {
        module_id == holder
            || module_id
                .strip_prefix("com.core.")
                .is_some_and(|short| short == holder)
    }
}

/// Derive the configured-holder record from the generated case.
///
/// `top` and `sparse` use the short form for a `com.core.*` holder, `bottom`
/// uses the full id and `bridge` names a different module, so both matching
/// branches and the non-matching branch are exercised.
fn selection_fill_holders(case: &ClaimCase) -> SelectionFillHolders {
    let fill_holder = case
        .claim_holders
        .iter()
        .find(|holder| holder.claim == FILL_CLAIM_IDS[0])
        .map(|holder| holder.module_id.clone())
        .expect("the fixed four-role fill setup always names a holder");
    let short = fill_holder
        .strip_prefix("com.core.")
        .map_or_else(|| fill_holder.clone(), String::from);
    let non_holder = case
        .modules
        .iter()
        .map(LoadedModule::id)
        .rfind(|id| *id != fill_holder.as_str())
        .map_or_else(|| String::from("com.pbt.not-a-module"), String::from);
    SelectionFillHolders {
        top: short,
        bottom: fill_holder.clone(),
        bridge: non_holder,
        sparse: fill_holder,
    }
}

/// The independent selector-table model for one selection/pairing case.
fn selection_expectation(case: &ClaimCase) -> SelectionExpectation {
    let witness = match case.mode {
        ClaimMode::SelectionPairing(witness) => witness,
        _ => panic!("the selector model only models ClaimMode::SelectionPairing"),
    };

    let mut sorted: Vec<&LoadedModule> = case.modules.iter().collect();
    sorted.sort_by(|left, right| left.id().cmp(right.id()));

    // Pass 1: (stage, claim) -> lexical candidates, skipping fill claims and
    // the family scope marker.
    let mut candidates: BTreeMap<(String, String), Vec<ModuleId>> = BTreeMap::new();
    for module in &sorted {
        for claim in module.claims() {
            if FILL_CLAIM_IDS.contains(&claim.as_str()) || claim.starts_with("support-family:") {
                continue;
            }
            candidates
                .entry((module.stage().to_string(), claim.clone()))
                .or_default()
                .push(module.id().to_string());
        }
    }

    let family_scoped: BTreeSet<&str> = sorted
        .iter()
        .filter(|module| {
            module
                .claims()
                .iter()
                .any(|claim| claim.starts_with("support-family:"))
        })
        .map(|module| module.id())
        .collect();

    // Pass 2: resolve one winner per contested (stage, claim).
    let mut winners: BTreeMap<(String, String), ModuleId> = BTreeMap::new();
    for ((stage, claim), ids) in &candidates {
        if ids.len() < 2 {
            continue;
        }
        let winner = if claim == "perimeter-generator" {
            let preferred = witness.preferred_perimeter();
            if ids.iter().any(|id| id == preferred) {
                preferred.to_string()
            } else {
                ids[0].clone()
            }
        } else if claim == "support-generator" {
            // Renderers are selected per region at dispatch time.
            continue;
        } else if claim == "support-planner" {
            // Family-scoped planners coexist; only non-family planners resolve
            // alphabetically.
            let global: Vec<&ModuleId> = ids
                .iter()
                .filter(|id| !family_scoped.contains(id.as_str()))
                .collect();
            if global.len() < 2 {
                continue;
            }
            global[0].clone()
        } else {
            ids[0].clone()
        };
        winners.insert((stage.clone(), claim.clone()), winner);
    }

    // Pass 3: keep every module whose claims all match their winner.
    let mut kept: Vec<ModuleId> = Vec::new();
    let mut drops: Vec<SelectionDrop> = Vec::new();
    for module in &sorted {
        let mut losing: Option<(String, ModuleId)> = None;
        for claim in module.claims() {
            if FILL_CLAIM_IDS.contains(&claim.as_str()) || claim == "support-generator" {
                continue;
            }
            if claim == "support-planner" && family_scoped.contains(module.id()) {
                continue;
            }
            if let Some(winner) = winners.get(&(module.stage().to_string(), claim.clone())) {
                if winner != module.id() {
                    losing = Some((claim.clone(), winner.clone()));
                    break;
                }
            }
        }
        match losing {
            Some((claim, winner)) => drops.push(SelectionDrop {
                module: module.id().to_string(),
                stage: module.stage().to_string(),
                claim,
                winner,
            }),
            None => kept.push(module.id().to_string()),
        }
    }

    // Pass 4: family pairing over the retained modules only.
    let kept_set: BTreeSet<&str> = kept.iter().map(String::as_str).collect();
    let mut planners: BTreeSet<String> = BTreeSet::new();
    let mut renderers: BTreeSet<String> = BTreeSet::new();
    for module in &sorted {
        if !kept_set.contains(module.id()) {
            continue;
        }
        let is_planner = module
            .claims()
            .iter()
            .any(|claim| claim == "support-planner");
        let is_renderer = module
            .claims()
            .iter()
            .any(|claim| claim == "support-generator");
        for claim in module.claims() {
            let Some(family) = claim.strip_prefix("support-family:") else {
                continue;
            };
            if is_planner {
                planners.insert(family.to_string());
            }
            if is_renderer {
                renderers.insert(family.to_string());
            }
        }
    }
    let missing_renderers: Vec<String> = planners.difference(&renderers).cloned().collect();
    let missing_planners: Vec<String> = renderers.difference(&planners).cloned().collect();

    SelectionExpectation {
        kept,
        drops,
        missing_renderers,
        missing_planners,
    }
}

/// Independently model `resolve_held_claims` for one module.
fn model_held_claims(
    module_id: &str,
    declared: &[String],
    holders: &SelectionFillHolders,
) -> Vec<String> {
    declared
        .iter()
        .filter(|claim| {
            FILL_CLAIM_IDS.contains(&claim.as_str()) || claim.as_str() == "claim:raft-fill"
        })
        .filter(|claim| {
            claim.as_str() == "claim:raft-fill"
                || holders
                    .holder_for(claim)
                    .is_some_and(|holder| SelectionFillHolders::matches(module_id, holder))
        })
        .cloned()
        .collect()
}

/// Drive the three real selection/pairing seams and compare each result to the
/// independent selector table.
fn check_selection_case(
    case: &ClaimCase,
    witness: SelectionWitness,
    limits: &ClaimLimits,
) -> Result<(), TestCaseError> {
    // Premise: the declarative domain is exactly the budget-fitting ladder,
    // rotated only in declaration order.
    let expected_domain: BTreeSet<&str> = selection_modules(limits)
        .iter()
        .map(|entry| entry.0)
        .collect();
    let actual_domain: BTreeSet<&str> = case.modules.iter().map(LoadedModule::id).collect();
    prop_assert_eq!(
        &actual_domain,
        &expected_domain,
        "the generated selection domain must be exactly the budget-fitting ladder"
    );

    let expected = selection_expectation(case);

    // Seam 1: the typed `wall_generator` / `spiral_vase` dedup.
    let mut modules = case.modules.clone();
    let mut diagnostics: Vec<LoadDiagnostic> = Vec::new();
    let selector = witness.wall_generator();
    let kept = dedup_same_claim_modules_with_typed_wall_generator(
        &mut modules,
        &mut diagnostics,
        selector.as_ref(),
        witness.spiral_vase(),
        None,
    );
    let actual_kept: Vec<ModuleId> = kept.iter().map(|module| module.id().to_string()).collect();
    prop_assert_eq!(
        &actual_kept,
        &expected.kept,
        "the typed selector {:?} must keep exactly the modelled module sequence",
        witness
    );
    prop_assert_eq!(
        actual_kept.len() + diagnostics.len(),
        case.modules.len(),
        "every declaration must be either kept or dropped with one diagnostic"
    );
    prop_assert_eq!(
        diagnostics.len(),
        expected.drops.len(),
        "drop diagnostics must match the modelled losing modules"
    );
    for (diagnostic, drop) in diagnostics.iter().zip(&expected.drops) {
        prop_assert_eq!(
            diagnostic.level,
            DiagnosticLevel::Info,
            "a drop diagnostic must be Info"
        );
        prop_assert_eq!(
            diagnostic.field.as_deref(),
            Some("claims.holds"),
            "a drop diagnostic must point at claims.holds"
        );
        prop_assert_eq!(
            diagnostic.path.clone(),
            PathBuf::from("fixtures/pbt-placeholder.wasm"),
            "a drop diagnostic must retain the dropped module's wasm path"
        );
        let expected_message = format!(
            "module '{}' in stage '{}' dropped: claim '{}' already held by '{}' \
             (first-winner dedup; docs/04 §2)",
            drop.module, drop.stage, drop.claim, drop.winner
        );
        prop_assert_eq!(
            &diagnostic.message,
            &expected_message,
            "a drop diagnostic must name the claim and winner"
        );
    }

    // Seam 2: configured fill-role resolution with a `FillHolders` record.
    let holders = selection_fill_holders(case);
    let fill_holders = FillHolders {
        top: &holders.top,
        bottom: &holders.bottom,
        bridge: &holders.bridge,
        sparse: &holders.sparse,
    };
    for module in &case.modules {
        let declared = module.claims().to_vec();
        let actual = resolve_held_claims(module.id(), &declared, &fill_holders);
        let modelled = model_held_claims(module.id(), &declared, &holders);
        prop_assert_eq!(
            &actual,
            &modelled,
            "resolve_held_claims must retain exactly the configured fill roles declared by {}",
            module.id()
        );
    }

    // Seam 3: support family pairing over the actual retained modules.
    let warnings = validate_support_family_pairing(&kept)
        .expect("an incomplete support family pair must warn, never abort");
    let expected_warnings: Vec<SupportFamilyPairingError> =
        if expected.missing_renderers.is_empty() && expected.missing_planners.is_empty() {
            Vec::new()
        } else {
            vec![SupportFamilyPairingError {
                missing_renderers: expected.missing_renderers.clone(),
                missing_planners: expected.missing_planners.clone(),
            }]
        };
    prop_assert_eq!(
        &warnings,
        &expected_warnings,
        "support family pairing must report the exact sorted missing lists"
    );
    Ok(())
}

/// The distinguishing witness for a selection/pairing case, used by the shrink
/// audit: the perimeter contest, the retained fill/renderer/family-planner
/// modules and the preferred perimeter winner all survive rotation.
fn selection_witness_present(case: &ClaimCase) -> bool {
    let ClaimMode::SelectionPairing(witness) = case.mode else {
        return false;
    };
    let model = selection_expectation(case);
    let perimeter_candidates = case
        .modules
        .iter()
        .filter(|module| {
            module
                .claims()
                .iter()
                .any(|claim| claim == "perimeter-generator")
        })
        .count();
    if perimeter_candidates < 2 {
        return false;
    }
    if !model
        .kept
        .iter()
        .any(|id| id == witness.preferred_perimeter())
    {
        return false;
    }
    if model.kept.len() + model.drops.len() != case.modules.len() {
        return false;
    }
    case.modules.iter().all(|module| {
        let must_survive = module
            .claims()
            .iter()
            .any(|claim| FILL_CLAIM_IDS.contains(&claim.as_str()))
            || module
                .claims()
                .iter()
                .any(|claim| claim == "support-generator")
            || (module
                .claims()
                .iter()
                .any(|claim| claim == "support-planner")
                && module
                    .claims()
                    .iter()
                    .any(|claim| claim.starts_with("support-family:")));
        !must_survive || model.kept.iter().any(|id| id == module.id())
    })
}

fn selection_signature(case: &ClaimCase) -> u8 {
    let model = selection_expectation(case);
    let mut signature = 0u8;
    if !model.drops.is_empty() {
        signature |= 1;
    }
    if !model.missing_renderers.is_empty() || !model.missing_planners.is_empty() {
        signature |= 2;
    }
    if let ClaimMode::SelectionPairing(witness) = case.mode {
        if model
            .kept
            .iter()
            .any(|id| id == witness.preferred_perimeter())
        {
            signature |= 4;
        }
    }
    let fill_declarers: Vec<&LoadedModule> = case
        .modules
        .iter()
        .filter(|module| {
            module
                .claims()
                .iter()
                .any(|claim| FILL_CLAIM_IDS.contains(&claim.as_str()))
        })
        .collect();
    if !fill_declarers.is_empty()
        && fill_declarers
            .iter()
            .all(|module| model.kept.iter().any(|id| id == module.id()))
    {
        signature |= 8;
    }
    signature
}

// ─────────────────────────────────────────────────────────────────────────
// Population and shrink-preservation audit.
// ─────────────────────────────────────────────────────────────────────────

/// Bounded pre-sample: every available tagged mode is reached, positive and
/// negative verdicts both occur, and shrinking never erases the mode or the
/// verdict class.
pub fn assert_mode_and_verdict_population(
    strategy: &BoxedStrategy<ClaimCase>,
    limits: &ClaimLimits,
) {
    let mut runner = TestRunner::new(Config {
        cases: u32::try_from(PRE_SAMPLE_CASES).expect("bounded"),
        max_local_rejects: 0,
        rng_algorithm: RngAlgorithm::ChaCha,
        rng_seed: RngSeed::Fixed(0x0c1a_1155_0000_0007),
        failure_persistence: None,
        ..Config::default()
    });

    let mut modes = BTreeSet::new();
    let mut positive = 0usize;
    let mut negative = 0usize;

    for _ in 0..PRE_SAMPLE_CASES {
        let mut tree = strategy
            .new_tree(&mut runner)
            .expect("the H-CLAIMS strategy must not reject");
        let sampled = tree.current();
        let signature = verdict_signature(&sampled);
        for _ in 0..SHRINK_AUDIT_STEPS {
            if tree.simplify() {
                let shrunk = tree.current();
                assert_eq!(
                    shrunk.mode, sampled.mode,
                    "shrinking changed the tagged mode away from {:?}",
                    sampled.mode
                );
                assert_eq!(
                    verdict_signature(&shrunk),
                    signature,
                    "shrinking erased the verdict witness for mode {:?}: {}",
                    shrunk.mode,
                    describe_case(&shrunk)
                );
            } else {
                break;
            }
        }
        modes.insert(sampled.mode);
        if signature == 0 {
            negative += 1;
        } else {
            positive += 1;
        }
    }

    let available = available_modes(limits);
    for mode in &available {
        assert!(
            modes.contains(mode),
            "pre-sample of {PRE_SAMPLE_CASES} cases never reached mode {mode:?}"
        );
    }
    // The only filtered variants are the three-holder modes, and only when the
    // accepted observation budget cannot carry three extra observations. Making
    // that exclusion explicit stops a future bound change from silently
    // dropping a mode.
    for mode in ClaimMode::ALL {
        if available.contains(&mode) {
            continue;
        }
        assert!(
            matches!(mode, ClaimMode::StableThreeHolders(_)),
            "mode {mode:?} must not be silently unavailable"
        );
        assert!(
            limits.max_observations < 3,
            "mode {mode:?} was filtered although the bounds could carry it: {limits:?}"
        );
    }
    assert!(
        positive > 0,
        "pre-sample of {PRE_SAMPLE_CASES} cases never produced a rejecting verdict"
    );
    assert!(
        negative > 0,
        "pre-sample of {PRE_SAMPLE_CASES} cases never produced an accepting verdict"
    );
}

/// Bounded simplify audit: every available mode's *distinguishing* witness
/// survives shrinking, not just its verdict class.
///
/// This is the guard that a `Union`-style mode/branch switch cannot hide behind
/// a stable coarse signature: e.g. the cycle of scopes stays distinct, the
/// conflicting pair stays conflicting, the disabled consumer stays missing its
/// module, and the selector witness stays the same preferred perimeter.
pub fn assert_shrink_preserves_witnesses(
    strategy: &BoxedStrategy<ClaimCase>,
    limits: &ClaimLimits,
) {
    let mut runner = TestRunner::new(Config {
        cases: u32::try_from(PRE_SAMPLE_CASES).expect("bounded"),
        max_local_rejects: 0,
        rng_algorithm: RngAlgorithm::ChaCha,
        // Same seed as the population audit so the two audits sample the same
        // trees; coverage of every available mode is asserted there.
        rng_seed: RngSeed::Fixed(0x0c1a_1155_0000_0007),
        failure_persistence: None,
        ..Config::default()
    });

    let mut witnessed = BTreeSet::new();
    for _ in 0..PRE_SAMPLE_CASES {
        let mut tree = strategy
            .new_tree(&mut runner)
            .expect("the H-CLAIMS strategy must not reject");
        let sampled = tree.current();
        assert!(
            witness_present(&sampled),
            "the sampled case does not carry its distinguishing witness for mode {:?}: {}",
            sampled.mode,
            describe_case(&sampled)
        );
        witnessed.insert(sampled.mode);
        for _ in 0..SHRINK_AUDIT_STEPS {
            if tree.simplify() {
                let shrunk = tree.current();
                assert_eq!(
                    shrunk.mode, sampled.mode,
                    "shrinking switched the tagged mode away from {:?}",
                    sampled.mode
                );
                assert!(
                    witness_present(&shrunk),
                    "shrinking erased the distinguishing witness for mode {:?}: {}",
                    shrunk.mode,
                    describe_case(&shrunk)
                );
            } else {
                break;
            }
        }
    }

    for mode in available_modes(limits) {
        assert!(
            witnessed.contains(&mode),
            "the shrink audit never sampled mode {mode:?}"
        );
    }
}

fn verdict_signature(case: &ClaimCase) -> u8 {
    if matches!(case.mode, ClaimMode::SelectionPairing(_)) {
        return selection_signature(case);
    }
    let mut signature = 0u8;
    for diagnostic in expected_diagnostics(case) {
        signature |= match diagnostic {
            DiagKey::Claim {
                pass: PassTag::GlobalClaims,
                ..
            } => 1,
            DiagKey::Claim {
                pass: PassTag::PerRegionClaims,
                ..
            } => 2,
            DiagKey::Missing { .. } => 4,
            DiagKey::Write { .. } => 8,
            DiagKey::CrossStage { .. } => 16,
            _ => 64,
        };
    }
    if !expected_transitive_modules(&case.enabled_modules()).is_empty() {
        signature |= 32;
    }
    signature
}

/// Whether the case still carries the witness its mode is named for.
fn witness_present(case: &ClaimCase) -> bool {
    match case.mode {
        ClaimMode::FillGlobalMultiplicity(claim) | ClaimMode::FamilyGlobalExempt(claim) => {
            distinct_global_holders(case, claim) >= 2
        }
        ClaimMode::FillGlobalAbsent(claim) => !case
            .enabled_holders()
            .iter()
            .any(|holder| holder.claim == claim),
        ClaimMode::FillRegionDuplicate(claim) => region_holder_groups(case, claim)
            .values()
            .any(|modules| modules.len() >= 2),
        ClaimMode::RaftGlobal => distinct_global_holders(case, RAFT_CLAIM) >= 2,
        ClaimMode::FamilySuffixNotExempt => case.enabled_holders().iter().any(|holder| {
            holder.claim.starts_with("support-family:")
                && !FAMILY_SUPPORT_GLOBAL_CLAIMS.contains(&holder.claim.as_str())
        }),
        ClaimMode::OrdinaryGlobal => distinct_global_holders(case, ORDINARY_CLAIM) >= 2,
        ClaimMode::RegionScopes => region_holder_groups(case, "claim:region-0")
            .values()
            .any(|modules| modules.len() >= 2),
        ClaimMode::DelimiterScopes => assert_delimiter_witness(case).is_ok(),
        ClaimMode::WriteConflicts => expected_diagnostics(case)
            .iter()
            .any(|diagnostic| matches!(diagnostic, DiagKey::Write { .. })),
        ClaimMode::MissingUniverse => expected_diagnostics(case).iter().any(|diagnostic| {
            matches!(
                diagnostic,
                DiagKey::Missing {
                    pass: PassTag::Missing,
                    ..
                }
            )
        }),
        ClaimMode::CrossStage => expected_diagnostics(case)
            .iter()
            .any(|diagnostic| matches!(diagnostic, DiagKey::CrossStage { .. })),
        ClaimMode::CrossStageSharedStage => shared_stage_witness(case),
        ClaimMode::DisabledUniverse => disabled_witness(case),
        ClaimMode::StableSameRegion(claim) => stable_pair_witness(case, claim, false),
        ClaimMode::StableCrossRegion(claim) => stable_pair_witness(case, claim, true),
        ClaimMode::StableThreeHolders(claim) => stable_three_witness(case, claim),
        ClaimMode::StableSameModuleAcrossLayers => {
            let observations = region_observations(case, STABLE_CLAIM_IDS[0]);
            let mut layers: BTreeMap<&str, BTreeSet<Option<u32>>> = BTreeMap::new();
            for (module, _, _, layer) in &observations {
                layers.entry(module.as_str()).or_default().insert(*layer);
            }
            layers.values().any(|layers| layers.len() >= 2)
        }
        ClaimMode::StableDistinctObjects => {
            let observations = region_observations(case, STABLE_CLAIM_IDS[0]);
            let objects: BTreeSet<&str> = observations
                .iter()
                .map(|(_, object, _, _)| object.as_str())
                .collect();
            objects.len() >= 2
        }
        ClaimMode::TransitionCapable(claim) => stable_pair_witness(case, claim, false),
        ClaimMode::SelectionPairing(_) => selection_witness_present(case),
    }
}

fn distinct_global_holders(case: &ClaimCase, claim: &str) -> usize {
    case.enabled_holders()
        .iter()
        .filter(|holder| holder.claim == claim && matches!(holder.scope, ConflictScope::Global))
        .map(|holder| holder.module_id.clone())
        .collect::<BTreeSet<_>>()
        .len()
}

/// `(object, region, layer) -> distinct modules` for one claim's region holders.
fn region_holder_groups(
    case: &ClaimCase,
    claim: &str,
) -> BTreeMap<(String, String, Option<u32>), BTreeSet<ModuleId>> {
    let mut groups: BTreeMap<(String, String, Option<u32>), BTreeSet<ModuleId>> = BTreeMap::new();
    for holder in case.enabled_holders() {
        if holder.claim != claim {
            continue;
        }
        if let ConflictScope::Region {
            object_id,
            region_id,
            global_layer_index,
        } = &holder.scope
        {
            groups
                .entry((object_id.clone(), region_id.clone(), *global_layer_index))
                .or_default()
                .insert(holder.module_id);
        }
    }
    groups
}

/// `(module, object, region, layer)` for one claim's region holders.
fn region_observations(
    case: &ClaimCase,
    claim: &str,
) -> Vec<(ModuleId, String, String, Option<u32>)> {
    case.enabled_holders()
        .iter()
        .filter_map(|holder| {
            if holder.claim != claim {
                return None;
            }
            match &holder.scope {
                ConflictScope::Region {
                    object_id,
                    region_id,
                    global_layer_index,
                } => Some((
                    holder.module_id.clone(),
                    object_id.clone(),
                    region_id.clone(),
                    *global_layer_index,
                )),
                ConflictScope::Global => None,
            }
        })
        .collect()
}

fn stable_pair_witness(case: &ClaimCase, claim: &str, cross_region: bool) -> bool {
    let observations = region_observations(case, claim);
    for left in 0..observations.len() {
        for right in (left + 1)..observations.len() {
            let (left_module, left_object, left_region, left_layer) = &observations[left];
            let (right_module, right_object, right_region, right_layer) = &observations[right];
            if left_module == right_module || left_object != right_object {
                continue;
            }
            if cross_region {
                if left_region != right_region {
                    return true;
                }
            } else if left_region == right_region && left_layer != right_layer {
                return true;
            }
        }
    }
    false
}

fn stable_three_witness(case: &ClaimCase, claim: &str) -> bool {
    let observations = region_observations(case, claim);
    let modules: BTreeSet<&str> = observations
        .iter()
        .map(|(module, _, _, _)| module.as_str())
        .collect();
    let objects: BTreeSet<&str> = observations
        .iter()
        .map(|(_, object, _, _)| object.as_str())
        .collect();
    let regions: BTreeSet<&str> = observations
        .iter()
        .map(|(_, _, region, _)| region.as_str())
        .collect();
    let layers: BTreeSet<Option<u32>> =
        observations.iter().map(|(_, _, _, layer)| *layer).collect();
    modules.len() == 3 && objects.len() == 1 && regions.len() == 3 && layers.len() >= 2
}

fn shared_stage_witness(case: &ClaimCase) -> bool {
    let modules = case.enabled_modules();
    if modules.len() != 3 {
        return false;
    }
    let left = &modules[0];
    let middle = &modules[1];
    let right = &modules[2];
    left.stage() == middle.stage()
        && stage_ranks()
            .get(right.stage())
            .is_some_and(|rank| *rank > stage_ranks()[middle.stage()])
        && left.requires_modules().iter().any(|id| id == middle.id())
        && middle.requires_modules().iter().any(|id| id == right.id())
        && !left.requires_modules().iter().any(|id| id == right.id())
}

fn disabled_witness(case: &ClaimCase) -> bool {
    if case.disabled.is_empty() {
        return false;
    }
    let enabled_modules = case.enabled_modules();
    let enabled: BTreeSet<&str> = enabled_modules.iter().map(LoadedModule::id).collect();
    if case
        .disabled
        .iter()
        .any(|disabled| enabled.contains(disabled.as_str()))
    {
        return false;
    }
    enabled_modules.iter().any(|module| {
        module
            .requires_modules()
            .iter()
            .any(|required| case.disabled.iter().any(|disabled| disabled == required))
    })
}

fn describe_case(case: &ClaimCase) -> String {
    let modules: Vec<&str> = case.modules.iter().map(LoadedModule::id).collect();
    let holders: Vec<(String, String, String)> = case
        .claim_holders
        .iter()
        .map(|holder| {
            let scope = match &holder.scope {
                ConflictScope::Global => String::from("global"),
                ConflictScope::Region {
                    object_id,
                    region_id,
                    global_layer_index,
                } => format!("region({object_id:?}, {region_id:?}, {global_layer_index:?})"),
            };
            (holder.claim.clone(), holder.module_id.clone(), scope)
        })
        .collect();
    let dags: Vec<(String, Vec<String>)> = case
        .stage_dags
        .iter()
        .map(|dag| {
            (
                dag.stage.clone(),
                dag.nodes
                    .iter()
                    .map(|node| node.module_id.clone())
                    .collect(),
            )
        })
        .collect();
    format!(
        "mode={:?} modules={modules:?} holders={holders:?} dags={dags:?} disabled={:?}",
        case.mode, case.disabled
    )
}

// ─────────────────────────────────────────────────────────────────────────
// Small helpers.
// ─────────────────────────────────────────────────────────────────────────

fn semver(major: u32, minor: u32, patch: u32) -> SemVer {
    SemVer {
        major,
        minor,
        patch,
    }
}

fn module_ids(count: usize, text: &str) -> Vec<String> {
    (0..count)
        .map(|index| format!("com.pbt.claim-{index}-{text}"))
        .collect()
}

fn plain_modules(ids: &[String], stage: &str) -> Vec<LoadedModule> {
    ids.iter().map(|id| plain_module(id, stage)).collect()
}

fn uuid_text(limits: &ClaimLimits) -> BoxedStrategy<String> {
    // `checked_claim_limits` already rejected every ceiling below the 36-byte
    // UUID syntax floor, so the accepted bound is used exactly as given: the
    // generator must never widen a bound after it was accepted.
    id_text(IdTextKind::UuidSyntax, usize_bound(limits.max_text_bytes))
        .expect("UUID object-id domain inside the accepted 36..=64 bound")
}

fn raw_text(limits: &ClaimLimits) -> BoxedStrategy<String> {
    let max_bytes = usize_bound(limits.max_text_bytes);
    id_text(IdTextKind::OtherText, max_bytes)
        .expect("delimiter-rich id domain")
        .prop_map(|mut text| {
            // The packet's variable-id floor is 8 bytes; the shared domain can
            // emit shorter (even empty) text, so pad with ASCII to the floor.
            // `max_bytes >= 36`, so padding never exceeds the accepted ceiling.
            while text.len() < 8 {
                text.push('x');
            }
            text
        })
        .boxed()
}

fn usize_bound(bound: u64) -> usize {
    usize::try_from(bound).expect("checked_claim_limits rejects non-usize bounds")
}

fn u32_bound(bound: u64) -> u32 {
    u32::try_from(bound).expect("checked_claim_limits rejects non-u32 bounds")
}

fn two_layers(raw: u32, max_layers: u32) -> (u32, u32) {
    let first = raw % max_layers;
    (first, (first + 1) % max_layers)
}

fn ensure_distinct(left: String, right: String) -> (String, String) {
    if left == right {
        let mut adjusted = right;
        adjusted.replace_range(..1, if adjusted.starts_with('0') { "1" } else { "0" });
        (left, adjusted)
    } else {
        (left, right)
    }
}

// ─────────────────────────────────────────────────────────────────────────
// Property entry point.
// ─────────────────────────────────────────────────────────────────────────

/// Run the registry-selected `H-CLAIMS` property.
pub fn run_property() {
    let run = PropertyRun::new("H-CLAIMS", "proptest_scheduler_claim_models")
        .expect("H-CLAIMS registry context");
    let limits = checked_claim_limits(
        run.bound("max_modules").expect("max_modules bound"),
        run.bound("max_claims").expect("max_claims bound"),
        run.bound("max_observations")
            .expect("max_observations bound"),
        run.bound("max_layers").expect("max_layers bound"),
        run.bound("max_text_bytes").expect("max_text_bytes bound"),
    )
    .expect("H-CLAIMS safety ceilings");

    let strategy = claim_case_strategy(&limits);
    assert_mode_and_verdict_population(&strategy, &limits);
    assert_shrink_preserves_witnesses(&strategy, &limits);
    run.check(&strategy, |case, _guard| check_claim_case(&case, &limits))
        .expect("H-CLAIMS claim, write and dependency contract");
}
